/**
 * 本文に現れる図表番号を、キャプションと本文参照に分けて一覧する。
 *
 * 図表関係のルールと同じ解析を使うので、キャプションの先頭だけを本文参照として
 * 二重に数えたり、「Figure 1 に示す」をキャプションと誤認したりしない。
 */
import type { Occurrence } from "./inventory.ts";
import { intextRefs, normalizeLabel, parseCaption } from "./rules/figure.ts";

/**
 * 一覧に並べる種類と、その並び順。
 *
 * 図表ルールが読める見出しと同じ顔ぶれにしてある。ここが Figure と Table だけ
 * だった頃は、Scheme 1 の原稿が校正では指摘されるのに一覧には 1 行も出なかった。
 */
export const FIGURE_KINDS = ["Figure", "Table", "Scheme", "Chart", "Equation", "図", "表", "スキーム"] as const;

/** 番号を続けて書く見出し。「図1」であって「図 1」ではない。 */
const JAPANESE_KINDS: readonly string[] = ["図", "表", "スキーム"];

export interface FigureTableItem {
  /** 一覧に表示する正規化済みの番号（例：Figure 1、表2）。 */
  readonly label: string;
  readonly kind: (typeof FIGURE_KINDS)[number];
  readonly number: number;
  readonly captions: readonly Occurrence[];
  readonly references: readonly Occurrence[];
  /**
   * 番号の後ろに続くキャプション本文（「Absorption spectra of 1 and 2」）。
   * キャプションが無ければ空。2 つ以上あるときは最初のもの。
   *
   * 一覧が持つのは、これが**その番号が何の図なのかを言う唯一の文字**だから。
   * 「Figure 1 キャプション p.2 ¶5」 は、どこにあるかは言うが何かは言わない。
   */
  readonly captionText: string;
}

/** 番号ごとに、一覧で目に留めてほしい引っかかり。 */
export type FigureTableIssue = "キャプションなし" | "キャプションが 2 つ以上" | "本文で参照なし";

export interface MissingFigureNumber {
  readonly kind: FigureTableItem["kind"];
  readonly number: number;
  readonly label: string;
}

/**
 * 見出しの綴りを一覧の種類に寄せる。「Figs.」も「Fig.」も Figure に集まるので、
 * 「Fig. 1」のキャプションと「Figure 1」の本文参照が別の行に割れることはない。
 */
function kindFor(label: string): FigureTableItem["kind"] | null {
  const normalized = normalizeLabel(label);
  return FIGURE_KINDS.find((kind) => kind === normalized) ?? null;
}

function itemLabel(kind: FigureTableItem["kind"], number: number): string {
  return JAPANESE_KINDS.includes(kind) ? `${kind}${number}` : `${kind} ${number}`;
}

/** キャプションと本文中の参照を、図表番号ごとに束ねる。 */
export function figureTableInventory(paragraphs: readonly string[]): FigureTableItem[] {
  interface Draft {
    kind: FigureTableItem["kind"];
    number: number;
    captions: Occurrence[];
    references: Occurrence[];
    captionText: string;
  }
  const items = new Map<string, Draft>();
  const ensure = (kind: FigureTableItem["kind"], number: number): Draft => {
    const label = itemLabel(kind, number);
    const existing = items.get(label);
    if (existing) return existing;
    const created: Draft = { kind, number, captions: [], references: [], captionText: "" };
    items.set(label, created);
    return created;
  };

  paragraphs.forEach((text, paragraphIndex) => {
    const caption = parseCaption(text);
    const captionKind = caption ? kindFor(caption.label) : null;
    if (caption && captionKind) {
      const item = ensure(captionKind, caption.number);
      item.captions.push({
        paragraphIndex,
        start: caption.headStart,
        text: caption.head,
      });
      if (item.captionText === "") item.captionText = caption.body;
    }

    for (const reference of intextRefs(text)) {
      const kind = kindFor(reference.label);
      // A caption's own head is a label, not a sentence that refers to itself.
      if (!kind || (caption && reference.start < caption.headEnd)) continue;
      for (const number of reference.numbers) {
        ensure(kind, number).references.push({ paragraphIndex, start: reference.start, text: reference.text });
      }
    }
  });

  return [...items.entries()]
    .map(([label, item]) => ({ label, ...item }))
    .sort((a, b) => FIGURE_KINDS.indexOf(a.kind) - FIGURE_KINDS.indexOf(b.kind) || a.number - b.number);
}

/** その番号について確認したいこと。何もなければ空。 */
export function figureTableIssues(item: FigureTableItem): FigureTableIssue[] {
  const issues: FigureTableIssue[] = [];
  if (item.captions.length === 0) issues.push("キャプションなし");
  if (item.captions.length > 1) issues.push("キャプションが 2 つ以上");
  if (item.references.length === 0) issues.push("本文で参照なし");
  return issues;
}

/** その番号が最初に出てくる段落。キャプションと本文参照の早いほう。 */
export function figureFirstAt(item: FigureTableItem): number {
  const paragraphs = [...item.captions, ...item.references].map((occurrence) => occurrence.paragraphIndex);
  return paragraphs.length === 0 ? Number.POSITIVE_INFINITY : Math.min(...paragraphs);
}

/**
 * 見つかった番号のあいだに空いている番号。
 *
 * 最小番号より前は数えない。選択範囲だけを走査していると Figure 3 から始まるのは
 * 普通で、そこで「1 と 2 がない」と言えば毎回外れる。1 と 3 があって 2 がない、と
 * いう文書の中だけで確かめられる抜けに限る。
 */
export function missingFigureNumbers(items: readonly FigureTableItem[]): MissingFigureNumber[] {
  const byKind = new Map<FigureTableItem["kind"], number[]>();
  for (const item of items) {
    const numbers = byKind.get(item.kind) ?? [];
    numbers.push(item.number);
    byKind.set(item.kind, numbers);
  }

  const missing: MissingFigureNumber[] = [];
  for (const [kind, numbers] of byKind) {
    const found = new Set(numbers);
    for (let number = Math.min(...numbers) + 1; number < Math.max(...numbers); number += 1) {
      if (!found.has(number)) missing.push({ kind, number, label: itemLabel(kind, number) });
    }
  }
  return missing;
}

/** 番号順に並べたとき、本文での初出が前後しているか。 */
export function figuresOutOfOrder(items: readonly FigureTableItem[]): boolean {
  const byKind = new Map<FigureTableItem["kind"], FigureTableItem[]>();
  for (const item of items) {
    const group = byKind.get(item.kind) ?? [];
    group.push(item);
    byKind.set(item.kind, group);
  }

  for (const group of byKind.values()) {
    const firstAt = [...group].sort((a, b) => a.number - b.number).map(figureFirstAt);
    if (firstAt.some((at, i) => i > 0 && at < firstAt[i - 1]!)) return true;
  }
  return false;
}
