/**
 * 文献リストの項目と、Crossref が返した候補を突き合わせる.
 *
 * 候補を出すだけでは、99 件の原稿では何の役にも立たない。**題名と DOI が出て
 * いても、それが自分の書いた誌名・年・巻・ページと合っているかは、人が 99 回
 * 見比べるしかなかった。** ここはその見比べを機械にやらせる部分で、Crossref を
 * 有効にする本当の理由。
 *
 * ## 「違う」と言うときの慎重さ
 *
 * 照会は書誌の文字列 1 本で投げ、いちばん上の 1 件を採る。つまり **候補そのもの
 * が別の論文であることがある**。だから出すのは「間違っています」ではなく
 * 「候補と食い違います」で、突き合わせる項目も、ずれたら人が必ず確かめたく
 * なるものだけに絞ってある：
 *
 * - **年・巻・先頭ページ** — 数字なので解釈の余地がない。
 * - **筆頭著者の姓** — 論文そのものが違うときは、ここがまず動く。
 * - **誌名** — 原稿は略記（`Tetrahedron Lett.`）、Crossref は正式名
 *   （`Tetrahedron Letters`）。単純比較では全件が「違う」になるので、
 *   略語が正式名の語頭に順に対応するかで見る（`journalMatches`）。
 *
 * 片方が欠けている項目は黙って飛ばす。原稿に巻が無いのは書式の話で、
 * この機能の言うことではない。
 */

/** 突き合わせられる項目。 */
export type CrossrefField = "year" | "volume" | "page" | "journal" | "author";

/** 食い違い 1 件。原稿側と候補側の値をそのまま持つ。 */
export interface CrossrefMismatch {
  readonly field: CrossrefField;
  /** 原稿に書いてある値。 */
  readonly manuscript: string;
  /** Crossref の候補が持つ値。 */
  readonly candidate: string;
}

/** 突き合わせに使う分だけを抜き出した Crossref の 1 件。 */
export interface CrossrefFacts {
  readonly journal?: string;
  /** `short-container-title`。あれば誌名の比較はこちらを先に使う。 */
  readonly shortJournal?: string;
  /**
   * 候補が名乗る出版年。**複数あるのは意図的** —— 電子版が前年、冊子版が翌年に
   * なる論文があり、そのどちらを書いても誤りではない。1 つでも一致すれば黙る。
   */
  readonly years: readonly number[];
  readonly volume?: string;
  /** ページ範囲の先頭（`1903-1910` なら `1903`）。 */
  readonly firstPage?: string;
  /** 筆頭著者の姓。 */
  readonly firstAuthor?: string;
}

/** 原稿の書誌から読み取れた分。読めなければ undefined。 */
export interface EntryFacts {
  readonly journal?: string;
  readonly year?: string;
  readonly volume?: string;
  readonly firstPage?: string;
  readonly firstAuthor?: string;
}

/** 「誌名 2017, 58, 1903」。この並びは文献リスト以外にはまず出てこない。 */
const JOURNAL_YEAR_VOLUME_PAGE =
  /([A-Za-z][A-Za-z.\s&:'’-]*?)\s+((?:19|20)\d{2})\s*,\s*(\d+)\s*(?:\([^)]*\))?\s*(?:,\s*([A-Za-z]?\d+))?/u;

/** 「B. Shan」「Shan, B.」「Y. Tanaka」。references.ts の同名と同じ形。 */
const FIRST_AUTHOR =
  /^\s*(?:\[\d+\]|\(\d+\)|\d+[.)])?\s*([A-Z][A-Za-z'’-]+(?:,\s*[A-Z]\.(?:\s*[A-Z]\.)*)?|(?:[A-Z]\.\s*)+[A-Z][A-Za-z'’-]+)/u;

/**
 * 原稿の書誌 1 行から、突き合わせに使う値を読む。
 *
 * 読めなかった項目は落とす —— 推測で埋めると、その推測どうしを比べて
 * 「食い違い」を作り出してしまう。
 */
export function parseEntryFacts(text: string): EntryFacts {
  const match = JOURNAL_YEAR_VOLUME_PAGE.exec(text);
  const author = FIRST_AUTHOR.exec(text)?.[1];
  const surname = author === undefined
    ? undefined
    : author.includes(",")
      ? author.slice(0, author.indexOf(","))
      : author.split(/\s+/u).pop();

  if (!match) return surname ? { firstAuthor: surname } : {};
  // 誌名の手前には著者が付いている。最後の区切り（, または ;）より後ろが誌名。
  const head = match[1]!.trim();
  const journal = head.replace(/^(?:[A-Z]\.\s*)+/u, "").trim();
  return {
    ...(journal.length > 0 ? { journal } : {}),
    year: match[2],
    volume: match[3],
    ...(match[4] ? { firstPage: match[4] } : {}),
    ...(surname ? { firstAuthor: surname } : {}),
  };
}

/** 比較用に均す：小文字にして、字と数字だけ残す。 */
function plain(value: string): string {
  return value.toLowerCase().replace(/[^a-z0-9]+/gu, "");
}

/**
 * 略記の誌名が正式名と同じものを指しているか.
 *
 * `J. Am. Chem. Soc.` と `Journal of the American Chemical Society` を同じと
 * 読む。略語の各語が、正式名の語に**順番どおり**語頭一致すればよい —— 正式名に
 * だけある `of` `the` は飛ばす。逆向き（正式名どうし）も語頭一致で通る。
 *
 * 順序を要求するのは、飛ばせる語を無制限に許すと
 * `Chem. Sci.` が `Science of Chemistry` に当たってしまうため。
 */
export function journalMatches(manuscript: string, candidate: string): boolean {
  const left = manuscript.toLowerCase().split(/[^a-z0-9]+/u).filter((word) => word.length > 0);
  const right = candidate.toLowerCase().split(/[^a-z0-9]+/u).filter((word) => word.length > 0);
  if (left.length === 0 || right.length === 0) return false;

  let at = 0;
  for (const word of left) {
    const found = right.findIndex((other, i) => i >= at && (other.startsWith(word) || word.startsWith(other)));
    if (found === -1) return false;
    at = found + 1;
  }
  return true;
}

/**
 * 原稿と候補の食い違いを並べる。無ければ空。
 *
 * 片方でも欠けている項目は比べない（欠けているのは書式の話で、ここの用件では
 * ない）。誌名は略記どうし・正式名どうしのどちらでも当たるよう、
 * `short-container-title` と `container-title` の両方を試す。
 */
export function compareWithCrossref(entry: EntryFacts, facts: CrossrefFacts): readonly CrossrefMismatch[] {
  const mismatches: CrossrefMismatch[] = [];

  if (entry.year !== undefined && facts.years.length > 0) {
    const year = Number(entry.year);
    if (!facts.years.includes(year)) {
      mismatches.push({ field: "year", manuscript: entry.year, candidate: facts.years.join("・") });
    }
  }

  if (entry.volume !== undefined && facts.volume !== undefined && plain(entry.volume) !== plain(facts.volume)) {
    mismatches.push({ field: "volume", manuscript: entry.volume, candidate: facts.volume });
  }

  if (entry.firstPage !== undefined && facts.firstPage !== undefined
      && plain(entry.firstPage) !== plain(facts.firstPage)) {
    mismatches.push({ field: "page", manuscript: entry.firstPage, candidate: facts.firstPage });
  }

  const journals = [facts.shortJournal, facts.journal].filter((name): name is string => name !== undefined);
  if (entry.journal !== undefined && journals.length > 0
      && !journals.some((name) => journalMatches(entry.journal!, name))) {
    mismatches.push({ field: "journal", manuscript: entry.journal, candidate: journals[0]! });
  }

  if (entry.firstAuthor !== undefined && facts.firstAuthor !== undefined
      && plain(entry.firstAuthor) !== plain(facts.firstAuthor)) {
    mismatches.push({ field: "author", manuscript: entry.firstAuthor, candidate: facts.firstAuthor });
  }

  return mismatches;
}

const FIELD_NAMES: Readonly<Record<CrossrefField, string>> = {
  year: "年",
  volume: "巻",
  page: "ページ",
  journal: "誌名",
  author: "筆頭著者",
};

/** 「年 2017 → 2018」。カードにそのまま出す 1 件分。 */
export function describeMismatch(mismatch: CrossrefMismatch): string {
  return `${FIELD_NAMES[mismatch.field]} ${mismatch.manuscript} → ${mismatch.candidate}`;
}
