// --- 無視した指摘を原稿に残す ----------------------------------------------
//
// 「無視」 is a judgement about one manuscript, so it is kept in that manuscript
// (see src/taskpane/docStore.ts). The pane used to hold the list in memory,
// which meant a draft corrected over several days greeted the user every
// morning with the findings they had already waved away.

const IGNORED_KEY = "document-corrector.ignored.v1";

/**
 * Brings back the ignores stored in this document.
 *
 * Called before anything is drawn, so the first check of the session already
 * hides them rather than showing them once and then taking them away.
 */
function restoreIgnored(): void {
  ignored.restore(parseIgnored(readDocumentValue(IGNORED_KEY)));
  // 点検前でも出す。ここに一覧が出ていることが、前回の無視が残っている証拠になる。
  renderIgnored();
}

/** Writes the list back, on every change the user makes to it. */
function saveIgnored(): void {
  writeDocumentValue(IGNORED_KEY, ignored.findings().slice(0, MAX_IGNORED));
}

function restoreCompoundNotes(): void {
  compoundNotes.clear();
  const raw = readDocumentValue(COMPOUND_NOTES_KEY);
  if (raw === null || typeof raw !== "object" || Array.isArray(raw)) return;
  for (const [label, value] of Object.entries(raw as Record<string, unknown>)) {
    if (value === null || typeof value !== "object" || Array.isArray(value)) continue;
    const source = value as Record<string, unknown>;
    if (typeof source.text !== "string") continue;
    const image =
      typeof source.image === "string" && source.image.startsWith("data:image/")
        ? source.image
        : undefined;
    compoundNotes.set(label, { text: source.text.slice(0, 10_000), ...(image ? { image } : {}) });
  }
}

function persistCompoundNotes(): void {
  writeDocumentValue(COMPOUND_NOTES_KEY, Object.fromEntries(compoundNotes));
}

/** Keeps a closed compound row's structure thumbnail in sync with its memo. */
function updateCompoundThumbnail(label: string): void {
  const image = compoundNotes.get(label)?.image;
  for (const thumbnail of document.querySelectorAll<HTMLImageElement>(".compound-thumbnail")) {
    if (thumbnail.dataset.compoundLabel !== label) continue;
    thumbnail.src = image ?? "";
    thumbnail.hidden = image === undefined;
    thumbnail.closest<HTMLElement>(".compound-item")?.classList.toggle("has-thumbnail", image !== undefined);
  }
}

// Images are stored in the document as base64, which is about one-third larger
// than the original file. A 5 MB upload therefore adds roughly 6.7 MB to the
// document data; this is deliberately allowed for experimental memo use.
const MAX_COMPOUND_IMAGE_BYTES = 5_000_000;

/** Creates the memo editor inside one compound's own expanded details. */
function compoundNoteEditor(label: string): HTMLElement {
  const editor = document.createElement("section");
  editor.className = "compound-note";
  const heading = document.createElement("p");
  heading.className = "compound-detail-heading";
  heading.textContent = "メモ";
  const textarea = document.createElement("textarea");
  textarea.className = "compound-note-text";
  textarea.rows = 1;
  textarea.value = compoundNotes.get(label)?.text ?? "";
  textarea.setAttribute("aria-label", `化合物 ${label} のメモ`);

  const pasteTarget = document.createElement("div");
  pasteTarget.className = "compound-image-paste";
  pasteTarget.tabIndex = 0;
  pasteTarget.setAttribute("role", "button");
  pasteTarget.textContent = "ここに画像を貼り付け（⌘V）";
  pasteTarget.onclick = () => pasteTarget.focus();
  const imageHeading = document.createElement("p");
  imageHeading.className = "compound-detail-heading compound-image-heading";
  imageHeading.textContent = "画像（最大 5 MB）";
  const fileLabel = document.createElement("label");
  fileLabel.className = "compound-image-file-button";
  fileLabel.textContent = "ファイルから選択";
  const fileInput = document.createElement("input");
  fileInput.id = `compound-image-${label}`;
  fileInput.type = "file";
  fileInput.accept = "image/*";
  fileInput.className = "compound-image-input";
  fileLabel.htmlFor = fileInput.id;
  const imageControls = document.createElement("div");
  imageControls.className = "compound-image-controls";
  imageControls.append(pasteTarget, fileLabel, fileInput);
  const preview = document.createElement("img");
  preview.className = "compound-image";
  preview.alt = `化合物 ${label} のメモの添付画像`;

  const showImage = (): void => {
    const image = compoundNotes.get(label)?.image;
    preview.src = image ?? "";
    preview.hidden = image === undefined;
  };
  showImage();

  const save = button("メモを保存", () => {
    const image = compoundNotes.get(label)?.image;
    compoundNotes.set(label, { text: textarea.value.slice(0, 10_000), ...(image ? { image } : {}) });
    persistCompoundNotes();
    setStatus(`化合物 ${label} のメモを原稿に保存しました。`);
  });
  save.classList.add("primary");
  const memoControls = document.createElement("div");
  memoControls.className = "compound-memo-controls";
  memoControls.append(textarea, save);

  const imageActions = document.createElement("div");
  imageActions.className = "row compact compound-image-actions";
  const clear = button("画像を外す", () => {
    compoundNotes.set(label, { text: textarea.value.slice(0, 10_000) });
    persistCompoundNotes();
    showImage();
    updateCompoundThumbnail(label);
    clear.hidden = true;
    setStatus(`化合物 ${label} の添付画像を外しました。`);
  });
  clear.hidden = compoundNotes.get(label)?.image === undefined;
  imageActions.append(clear);

  const attachImage = (image: File): void => {
    if (image.size > MAX_COMPOUND_IMAGE_BYTES) {
      setStatus("画像が大きすぎます。5 MB 以下の画像を選んでください。");
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result !== "string" || !reader.result.startsWith("data:image/")) {
        setStatus("画像を読み込めませんでした。");
        return;
      }
      compoundNotes.set(label, { text: textarea.value.slice(0, 10_000), image: reader.result });
      persistCompoundNotes();
      showImage();
      updateCompoundThumbnail(label);
      clear.hidden = false;
      setStatus(`化合物 ${label} のメモに画像を添付しました。`);
    };
    reader.onerror = () => setStatus("画像を読み込めませんでした。");
    reader.readAsDataURL(image);
  };
  editor.addEventListener("paste", (event) => {
    const image = Array.from(event.clipboardData?.items ?? [])
      .find((item) => item.type.startsWith("image/"))
      ?.getAsFile();
    if (!image) return;
    event.preventDefault();
    attachImage(image);
  });
  fileInput.onchange = () => {
    const image = fileInput.files?.[0];
    fileInput.value = "";
    if (image) attachImage(image);
  };
  editor.append(heading, memoControls, imageHeading, imageControls, preview, imageActions);
  return editor;
}

// --- パネルを閉じても失わないために ----------------------------------------
//
// Word for Mac forgets a sideloaded add-in when it quits, so the [Corrector]
// tab is missing on the next launch until the add-in is re-enabled by hand from
// [ホーム]>[アドイン]. The one lever an add-in has over that is the startup
// behavior: once this has run on a document, Word loads the add-in — and with it
// the ribbon tab — whenever *that* document is reopened. It does nothing for a
// document the add-in has never been opened in, which is why the first open is
// still manual. See run-code-on-document-open in the Office docs.

/** Asks Word to load this add-in again whenever this document is reopened. */
function stayLoaded(): void {
  // SharedRuntime 1.1. Older Word has no Office.addin at all; a host that
  // refuses (the web, a read-only document) must not take the pane down with it.
  Office.addin
    ?.setStartupBehavior?.(Office.StartupBehavior.load)
    .catch(() => undefined);
}

/**
 * Keeps the list in step when the pane comes back after its [×].
 *
 * Closing the pane only hides it — the shared runtime keeps running, so
 * `current` and the ignore list are still here and the list is redrawn as it
 * was. Without this the pane would come back showing whatever status line was
 * left over from before it was closed.
 */
function watchVisibility(): void {
  Office.addin?.onVisibilityModeChanged?.((message) => {
    if (message.visibilityMode !== Office.VisibilityMode.taskpane) return;
    // 出ているのが指摘一覧のときだけ。図・表などの一覧や使い方を見ている
    // ところへ「◯ ページを点検しました」を出すと、その画面の説明に見える。
    if (currentView !== "review") return;
    if (current) renderReview();
    else setStatus("リボンの［文書をチェック］＞［いま点検する］で、点検を始めます。");
  }).catch(() => undefined);
}

// --- 更新の案内 ------------------------------------------------------------
//
// The rules update themselves: the pane's JavaScript is fetched fresh from the
// distribution host every time it opens, so a corrected check reaches everybody
// without anyone lifting a finger — and without anyone being told.
//
// The manifest is the exception. Word copies it once at install time and never
// looks again, so a new ribbon button never arrives on its own. That, and only
// that, is worth saying out loud. `src/core/version.ts` explains the comparison.
//
// **知らせるのはアイコン 1 つ。** 中身は押したときの小窓に入っている。ここは
// 以前、指摘一覧の上に出る帯だった。用件は「都合のよいときに入れ直してくだ
// さい」でしかないのに、パネルを開くたび、数えたばかりの件数より上に出ていた。

/**
 * Puts the update icon in the title row when the installed manifest is behind
 * the published one, and writes 使い方 の「バージョン」 either way.
 *
 * The icon is the exception, not the rule: it appears only when there is
 * something to do about it. But that leaves someone who has *just* replaced the
 * manifest with nothing to look at, so the version line is filled in whatever
 * the answer, including when the check itself could not be made.
 */
function checkForUpdate(): void {
  void (async () => {
    const installed = installedVersion(location.search);
    const info = await fetchVersionInfo();
    byId("help-version").textContent = versionLine(installed, info?.manifestVersion);
    if (!info) return; // Offline, blocked, or not published yet. Nothing to say.
    if (!isOutdated(installed, info.manifestVersion)) return;
    showUpdateNotice(info, installed);
  })();
}

function showUpdateNotice(info: VersionInfo, installed: string | null): void {
  const note = byId("update-note");
  const current = installed ?? "不明（この仕組みより前の版）";
  note.textContent = info.note
    ? `${info.note}（お使いの版 ${current} → ${info.manifestVersion}）`
    : `リボンの構成が変わりました。マニフェストを入れ直してください（${current} → ${info.manifestVersion}）。`;

  const open = byId("update-open") as HTMLButtonElement;
  const url = info.url;
  if (!url) {
    open.hidden = true;
  } else {
    open.onclick = () => {
      // Office's own opener; a plain window.open is blocked in some hosts. When
      // it is missing too, the address is shown so it can be copied by hand.
      const opener = Office.context?.ui?.openBrowserWindow;
      if (typeof opener === "function") opener.call(Office.context.ui, url);
      else revealUpdateUrl(url);
    };
  }

  const toggle = byId("update-toggle") as HTMLButtonElement;
  toggle.title = `新しいバージョンがあります（${current} → ${info.manifestVersion}）`;
  setUpUpdatePopover();
  show("update-wrap", true);
}

/**
 * アイコンを押したら開き、外を押すか Esc で閉じる小窓.
 *
 * ［あとで］が閉じるのは小窓だけで、アイコンは残す。帯だった頃の［あとで］は
 * 知らせごと消していて、あとから読み直す道が無かった。
 */
function setUpUpdatePopover(): void {
  const { close } = setUpPopover("update-toggle", "update-popover");
  byId("update-dismiss").onclick = close;
}

function revealUpdateUrl(url: string): void {
  const element = byId("update-url");
  element.textContent = url;
  element.hidden = false;
}

// --- リボンのボタン --------------------------------------------------------
//
// This pane is the add-in's shared runtime (see <Runtimes> in the manifest), so
// the ribbon's ExecuteFunction buttons run right here and can drive the list
// below. Every command must call event.completed(), or the button stays busy.

type CommandEvent = { completed: () => void };

/** Brings the pane forward, so a ribbon click has somewhere to show its result. */
async function showPane(): Promise<void> {
  if (Office.addin?.showAsTaskpane) await Office.addin.showAsTaskpane();
}

/**
 * Wraps a handler as a ribbon command: pane forward, errors into the status line.
 *
 * `event.completed()` はパネルを前に出した時点で呼ぶ。処理のあとではない。
 *
 * Office は実行中のコマンドが完了するまで次のクリックを溜め込む。最後に呼んで
 * いた頃は、39 ページの原稿で文献を走査しているあいだリボンのどのボタンも
 * 無反応だった。クリックは捨てられておらず走査の後でまとめて動くので、かえって
 * 何が起きたのか分からなかった。
 *
 * 走査は共有ランタイムで動き続けるから、先に手を離しても途中で止まらない。
 * 手放すのはホストへのエラー通知だけで、エラーはもともと下のステータス行に出す。
 *
 * **パネルを前に出すのを待たずに走らせる。** `showAsTaskpane()` はホストへの
 * 往復で、待っていると「押してから画面が変わるまで」にその往復ぶんが上乗せに
 * なる。画面の書き換えはパネルが出ていなくてもできるので、出てきたときには
 * もう目的の画面になっている。
 */
function command(handler: () => Promise<void>): (event: CommandEvent) => void {
  return (event: CommandEvent) => {
    const shown = showPane();
    handler().catch((error: unknown) => {
      setStatus(`エラー: ${error instanceof Error ? error.message : String(error)}`);
    });
    shown.catch(() => undefined).finally(() => event.completed());
  };
}

function registerRibbonCommands(): void {
  // Word too old for SharedRuntime drops the whole VersionOverrides block, so
  // there is no ribbon to bind to — the pane must still come up.
  if (!Office.actions?.associate) return;

  Office.actions.associate("runReview", command(runReview));
  Office.actions.associate("showLastResult", command(async () => showLastResult()));
  Office.actions.associate("openSettings", command(() => openDialog("settings.html", "設定")));
  Office.actions.associate("highlightFindings", command(highlightFindings));
  Office.actions.associate("commentFindings", command(commentFindings));
  Office.actions.associate("clearComments", command(clearComments));
  Office.actions.associate("clearAllComments", command(clearAllComments));
  Office.actions.associate("clearHighlights", command(clearHighlights));
  Office.actions.associate("clearAllHighlights", command(clearAllHighlights));
  // 一覧の 4 つは、初回だけ走査してあとは開くだけ（`openList`）。
  Office.actions.associate("listCompounds", command(() => openList("compounds")));
  Office.actions.associate("listReferences", command(() => openList("references")));
  Office.actions.associate("listFigures", command(() => openList("figures")));
  Office.actions.associate("replaceFonts", command(() => openList("fonts")));
  Office.actions.associate("showHelp", command(async () => showHelp()));
}

// --- UI helpers ----------------------------------------------------------

function byId(id: string): HTMLElement {
  const element = document.getElementById(id);
  if (!element) throw new Error(`missing element #${id}`);
  return element;
}

function setStatus(message: string, busy = false): void {
  const status = byId("status");
  status.textContent = message;
  status.classList.toggle("working", busy);
}

function show(id: string, visible: boolean): void {
  byId(id).hidden = !visible;
}

/** Wraps an async handler with shared error reporting. */
function run(handler: () => Promise<void>): () => void {
  return () => {
    handler().catch((error: unknown) => {
      setStatus(`エラー: ${error instanceof Error ? error.message : String(error)}`);
    });
  };
}

function truncate(text: string, limit: number): string {
  const flat = text.replace(/\s+/gu, " ").trim();
  return flat.length <= limit ? flat : `${flat.slice(0, limit)}…`;
}

function button(label: string, onclick: () => void, className?: string): HTMLElement {
  const element = document.createElement("button");
  element.type = "button";
  element.textContent = label;
  if (className) element.className = className;
  element.onclick = onclick;
  return element;
}

// --- パネルの表示切り替え --------------------------------------------------
//
// The pane shows one thing at a time. 指摘一覧 is the default; the four list
// buttons on the ribbon each swap it for their own view, and every one of those
// offers the way back — a pane that strands the user in a list is worse than one
// with no lists at all.

type View = "review" | "compounds" | "references" | "figures" | "fonts" | "help";

const VIEWS: Readonly<Record<View, string>> = {
  review: "view-review",
  compounds: "view-compounds",
  references: "view-references",
  figures: "view-figures",
  fonts: "view-fonts",
  help: "view-help",
};

const VIEW_TITLES: Readonly<Record<View, string>> = {
  review: "点検結果",
  compounds: "化合物",
  references: "文献",
  figures: "図・表",
  fonts: "文字",
  help: "使い方",
};

/**
 * いま出ている画面。タイトル行の更新ボタンが、どれを数え直すかを決める。
 *
 * 開いた直後は使い方 — taskpane.html の hidden もそれに合わせてある。
 */
let currentView: View = "help";

/**
 * 数え直せる画面と、その数え直し方。
 *
 * 一覧の数字は走査した瞬間のもので、本文を直しても勝手には変わらない。
 * ここに載っている画面だけがタイトル行に更新ボタンを出す（点検結果と使い方は
 * リボンの［文書をチェック］・［使い方］がその役をするので載せない）。
 */
const RESCAN: Partial<Readonly<Record<View, () => Promise<void>>>> = {
  compounds: () => listCompounds(),
  references: () => listReferences(),
  figures: () => listFigures(),
  fonts: () => replaceFonts(),
};

/**
 * 走査の済んだ画面と、そのときの結果表示。
 *
 * リボンのボタンは走査の合図ではなく、行き先の名前である —— ［文献］は
 * 「文献を数え直せ」ではなく「文献の画面を見せろ」。20 ページの原稿では走査に
 * 分単位かかるので、押すたびに数え直していると、見に戻るだけの一押しが
 * そのつど待ち時間になっていた。数え直しはタイトル行の更新ボタンが受け持つ。
 *
 * 画面の中身そのものは各 `view-*` の中に残っているので、描き直しは要らない。
 * ここが覚えるのは、消えてしまう 2 つ —— 状態表示の行と、いつ数えたか。
 */
const scanned = new Map<View, { readonly status: string; readonly at: string }>();

/**
 * リボンからの一覧の開き方。初回だけ走査し、二度目からはただ見せる。
 *
 * 数字が古くなっていることは、タイトル行の 「10:42 現在」 が言っている。
 */
async function openList(view: View): Promise<void> {
  const done = scanned.get(view);
  if (!done) {
    await RESCAN[view]?.();
    return;
  }
  showView(view);
  setStatus(done.status);
}

/**
 * 使い方の画面。リボンの［使い方］と、パネルを開いた直後の初期画面。
 *
 * 状態表示は空にする。ここに「点検は［文書をチェック］から」と書くと、すぐ下の
 * 手順 1 と同じことを言う行がタイトルの下に居座り、その分だけ本文が下がる
 * （`.status:empty` が行ごと畳む）。
 */
function showHelp(): void {
  showView("help");
  setStatus("");
}

/**
 * 前回の点検結果へ戻る。リボンの［文書をチェック］＞
 * ［チェックせず前回の結果を表示］から。
 *
 * 点検し直さないことが、このボタンの全部。図・表などの一覧や使い方を見たあと、
 * 数分かかる走査をもう一度待たずに指摘一覧へ帰れる。
 */
function showLastResult(): void {
  showView("review");
  if (current) renderReview();
  else setStatus("まだ点検していません。リボンの［文書をチェック］＞［いま点検する］で始めます。");
}

function showView(view: View): void {
  currentView = view;
  for (const [name, id] of Object.entries(VIEWS)) show(id, name === view);
  const hasReferences = view === "references" && (lastLabels?.references.length ?? 0) > 0;
  show("reference-list-jump", hasReferences);
  // 設定できるのは一覧の見え方なので、一覧が無い画面には出さない。
  show("reference-settings-wrap", hasReferences);
  show("figure-settings-wrap", view === "figures" && lastFigures.length > 0);
  show("view-refresh-row", RESCAN[view] !== undefined);
  byId("view-scanned-at").textContent = scanned.get(view)?.at ?? "";
  byId("panel-title").textContent = VIEW_TITLES[view];
  byId("panel-head").classList.toggle("context-view", view !== "review");
  // The font inventory itself carries its count, so an old inspection message
  // must not make the dedicated view look like it is still a review result.
  if (view === "fonts") setStatus("");
}

// --- 設定 -----------------------------------------------------------------

function options(): ActionOptions {
  return {
    selectionOnly: prefs.selectionOnly,
    trackChanges: prefs.trackChanges,
    bodyFont: prefs.bodyFont,
    disabledRules: prefs.disabledRules,
    markerColors: prefs.markerColors,
    halfSpaceColor: prefs.halfSpaceColor,
    fullSpaceColor: prefs.fullSpaceColor,
    reviewOptions: {
      settings: { maxSentenceLength: prefs.maxSentenceLength },
      disabledEntries: prefs.disabledEntries,
    },
  };
}

// --- 設定ウィンドウ --------------------------------------------------------
//
// 「設定」 is a real Office dialog — its own window, which the user can move and
// keep open beside the document. A dialog is a separate runtime, so it cannot
// share `prefs` with this one: the current settings go out in the URL fragment,
// and the edited ones come back through `messageParent`.

/** The open window, or null. Office allows an add-in only one dialog at a time. */
let dialogWindow: Office.Dialog | null = null;
let dialogName = "";

function openDialog(page: string, name: string): Promise<void> {
  return new Promise((resolve) => {
    if (dialogWindow) {
      setStatus(`［${dialogName}］のウィンドウを閉じてから開いてください。`);
      resolve();
      return;
    }
    const url = new URL(page, location.href);
    // 設定ウィンドウの「バージョン」に出すため、パネル自身の ?v=（＝ Word に
    // 入っているマニフェストの版）をそのまま渡す。別ランタイムなので、聞ける
    // 相手が URL しかない。
    url.search = location.search;
    url.hash = encodeURIComponent(JSON.stringify(prefs));

    Office.context.ui.displayDialogAsync(
      url.href,
      { height: 70, width: 45, promptBeforeOpen: false },
      (result) => {
        if (result.status !== Office.AsyncResultStatus.Succeeded) {
          setStatus(`${name}を開けませんでした: ${result.error.message}`);
          resolve();
          return;
        }
        dialogWindow = result.value;
        dialogName = name;
        dialogWindow.addEventHandler(Office.EventType.DialogMessageReceived, onDialogMessage);
        // Fires when the user closes the window with its own [×].
        dialogWindow.addEventHandler(Office.EventType.DialogEventReceived, () => {
          dialogWindow = null;
        });
        resolve();
      },
    );
  });
}

function onDialogMessage(arg: unknown): void {
  const raw = (arg as { message?: string }).message ?? "";
  let close = false;
  try {
    const payload = JSON.parse(raw) as { prefs?: unknown; close?: unknown };
    prefs = normalize(payload.prefs);
    savePreferences(prefs);
    close = payload.close === true;
  } catch {
    return; // not ours, or truncated
  }

  if (!close) {
    // A color change should show in the list's swatches without a re-scan.
    if (current) renderReview();
    return;
  }
  dialogWindow?.close();
  dialogWindow = null;
  // 「閉じて再点検」 only re-scans if there is already a list to refresh.
  if (current) run(runReview)();
}


// --- チェックリストのレビュー ---------------------------------------------

async function runReview(): Promise<void> {
  showView("review");

  // 経過も出す。長い原稿では段階だけだと止まって見えるので、動いている
  // ことが分かる数字を添える。1 ページ数秒なので、論文では分を超える。
  const started = Date.now();
  const elapsed = (): string => {
    const seconds = Math.round((Date.now() - started) / 1000);
    return seconds < 3 ? "" : `　${seconds} 秒経過`;
  };

  setStatus("点検の準備をしています…", true);
  current = await actions.reviewDocument(options(), ({ step, of, what }) => {
    setStatus(`${what}…（${step}/${of}）${elapsed()}`, true);
  });
  [reviewedPages, pageOf] = await Promise.all([
    actions.documentPageCount(options()),
    actions.paragraphPages(current.findings.map((finding) => finding.paragraphIndex), options()),
  ]);
  renderReview();
}

function renderReview(): void {
  if (!current) return;
  const { findings, paragraphCount } = current;
  const live = ignored.filter(findings);

  renderResultSummary(live);
  renderConditionFilters(live);
  renderCategoryFilters(live);
  renderFindings(live);
  renderFixed();
  renderIgnored();

  // 点検が済んだら案内は引っこめる。以後は指摘一覧が本題。
  show("start-section", false);

  const hiddenCount = findings.length - live.length;
  const suffix = hiddenCount > 0 ? `（無視 ${hiddenCount} 件を除く）` : "";
  const scope = reviewedPages === null ? `${paragraphCount} 段落` : `${reviewedPages} ページ`;
  setStatus(
    live.length === 0
      ? `${scope}を点検しました。指摘はありません${suffix}。`
      : `${scope}を点検しました。未処理の指摘は ${live.length} 件です${suffix}。`,
  );
}

function renderResultSummary(findings: readonly Finding[]): void {
  byId("result-open-count").textContent = String(findings.length);
  byId("result-fixed-count").textContent = String(fixedRecords.length);
  byId("result-ignored-count").textContent = String(ignored.size);
  for (const element of document.querySelectorAll<HTMLElement>("[data-result-tab]")) {
    element.setAttribute("aria-pressed", String(element.dataset.resultTab === resultTab));
  }
  show("result-summary", true);
}

function renderCategoryFilters(findings: readonly Finding[]): void {
  const counts = groupByCategory(findings);
  const container = byId("category-filters");
  container.innerHTML = "";

  const present = (Object.keys(CATEGORIES) as Category[]).filter((id) => (counts.get(id)?.length ?? 0) > 0);
  show("summary-section", present.length > 0 && resultTab === "open");

  for (const id of present) {
    const info = CATEGORIES[id];
    const label = document.createElement("label");
    label.className = "filter";

    const box = document.createElement("input");
    box.type = "checkbox";
    box.checked = visibleCategories.has(id);
    box.onchange = () => {
      if (box.checked) visibleCategories.add(id);
      else visibleCategories.delete(id);
      if (current) renderFindings(ignored.filter(current.findings));
    };

    const swatch = document.createElement("span");
    swatch.className = "swatch";
    swatch.style.background = markerColor(prefs, id);
    swatch.title = "この色で塗られます（［設定］で変更できます）";

    const text = document.createElement("span");
    text.textContent = `${info.label}（${counts.get(id)!.length}）`;

    label.append(box, swatch, text);
    container.appendChild(label);
  }
}

function renderConditionFilters(findings: readonly Finding[]): void {
  const container = byId("condition-filters");
  container.innerHTML = "";
  const conditions: readonly { readonly severity: Finding["severity"]; readonly label: string }[] = [
    { severity: "fix", label: "自動修正可" },
    { severity: "confirm", label: "確認が必要" },
    { severity: "note", label: "内容を確認" },
  ];

  for (const { severity, label: text } of conditions) {
    const count = findings.filter((finding) => finding.severity === severity).length;
    if (count === 0) continue;
    const label = document.createElement("label");
    label.className = "filter";
    const box = document.createElement("input");
    box.type = "checkbox";
    box.checked = visibleSeverities.has(severity);
    box.onchange = () => {
      if (box.checked) visibleSeverities.add(severity);
      else visibleSeverities.delete(severity);
      if (current) renderFindings(ignored.filter(current.findings));
    };
    const copy = document.createElement("span");
    copy.textContent = `${text}（${count}）`;
    label.append(box, copy);
    container.appendChild(label);
  }
}

function renderFindings(findings: readonly Finding[]): void {
  const container = byId("findings");
  container.innerHTML = "";

  if (resultTab !== "open") {
    show("findings-section", false);
    return;
  }
  const visible = findings.filter(
    (finding) => visibleCategories.has(finding.category) && visibleSeverities.has(finding.severity),
  );
  byId("findings-title").textContent = "未修正";
  show("findings-section", true);
  if (visible.length === 0) {
    const empty = document.createElement("p");
    empty.className = "lead";
    empty.textContent =
      findings.length === 0
        ? "未処理の指摘はありません。"
        : "表示する条件またはカテゴリが選ばれていません。";
    container.appendChild(empty);
    return;
  }

  for (const [category, items] of groupByCategory(visible)) {
    const info = CATEGORIES[category];
    const group = document.createElement("details");
    group.className = "category-group";
    group.open = true;

    const summary = document.createElement("summary");
    const swatch = document.createElement("span");
    swatch.className = "swatch";
    swatch.style.background = markerColor(prefs, category);
    summary.append(swatch, document.createTextNode(`${info.label}（${items.length}）`));
    group.appendChild(summary);

    for (const [ruleId, ofRule] of groupByRule(items)) group.appendChild(ruleGroup(ruleId, ofRule));
    container.appendChild(group);
  }
}

// --- 同じ指摘をまとめる ----------------------------------------------------
//
// 「和文と英数字の間隔」 alone can fire eighty times in a manuscript, and reading
// eighty cards that all say the same thing is not reviewing. So the findings of
// one rule are collected under one heading that says what they have in common
// and how many there are, with the individual cards a disclosure triangle away.
//
// The heading carries the bulk actions. 「まとめて修正」 is the whole point: the
// spacing findings are identical edits, and confirming each one separately taught
// nobody anything.

/** How many spans the heading lists before it gives up and says 「ほか n 件」. */
const SAMPLE_LIMIT = 8;

function ruleGroup(ruleId: string, items: readonly Finding[]): HTMLElement {
  // One finding has nothing to summarise; the card already says everything.
  if (items.length === 1) return findingRow(items[0]!);

  const group = document.createElement("div");
  group.className = `finding severity-${dominantSeverity(items)}`;

  const head = document.createElement("div");
  head.className = "finding-head";
  const badge = document.createElement("span");
  badge.className = "badge";
  badge.textContent = titleFor(ruleId);
  const count = document.createElement("span");
  count.className = "severity";
  count.textContent = `${items.length} 件`;
  head.append(badge, count);

  // The spans themselves, which is what tells the reviewer at a glance whether
  // these really are all the same mistake.
  const quote = document.createElement("p");
  quote.className = "finding-quote";
  const shown = items.slice(0, SAMPLE_LIMIT).map((f) => truncate(f.matched, 16));
  quote.textContent =
    shown.join(" / ") + (items.length > shown.length ? ` ほか ${items.length - shown.length} 件` : "");
  const range = document.createElement("span");
  range.className = "page-range";
  range.textContent = pageRange(items);
  quote.appendChild(range);

  const buttons = document.createElement("div");
  buttons.className = "rule-actions";

  const fixable = items.filter(canFix);
  if (fixable.length > 0) {
    const label =
      fixable.length === items.length
        ? `${fixable.length} 件をまとめて修正`
        : `修正できる ${fixable.length} 件を修正`;
    buttons.appendChild(button(label, run(() => fixRule(ruleId)), "primary"));
  }

  const details = document.createElement("details");
  details.className = "one-by-one";
  const summary = document.createElement("summary");
  summary.hidden = true;
  summary.textContent = "個別の指摘";
  details.appendChild(summary);
  for (const item of items) details.appendChild(findingRow(item, false));
  let firstOpen = true;
  details.ontoggle = () => {
    if (!details.open || !firstOpen) return;
    firstOpen = false;
    run(async () => {
      const ok = await actions.revealFinding(items[0]!, options());
      const which = items.length > 1 ? `${items.length} 件のうち 1 件目` : "該当箇所";
      setStatus(
        ok
          ? `${which}を選択しました（${where(items[0]!.paragraphIndex)}）。`
          : "該当箇所が見つかりませんでした。再度チェックしてください。",
      );
    })();
  };

  buttons.appendChild(
    button("1 件ずつ確認", () => {
      details.open = !details.open;
    }, "review"),
  );
  buttons.appendChild(
    button("無視", () => {
      ignored.addAll(items);
      renderReview();
    }, "ignore"),
  );
  if (fixable.length === 0) buttons.classList.add("no-fix");

  group.append(head, quote, buttons, details);
  return group;
}

/** The severity the group's stripe shows: the most urgent one present. */
function dominantSeverity(items: readonly Finding[]): Finding["severity"] {
  if (items.some((f) => f.severity === "fix")) return "fix";
  if (items.some((f) => f.severity === "confirm")) return "confirm";
  return "note";
}

/**
 * Applies every fixable finding of one rule.
 *
 * More than one pass, because two findings of the same rule can overlap — 「その3
 * 種類」 wants a space on both sides of the 3 — and `orderForApply` keeps only one
 * of an overlapping pair rather than letting them corrupt each other. The
 * dropped one comes back in the next review, so the loop finishes what a single
 * pass could not. Three passes is a bound, not an expectation: one is the normal
 * case, and the loop stops as soon as a pass changes nothing.
 */
const MAX_FIX_PASSES = 3;

async function fixRule(ruleId: string): Promise<void> {
  const name = titleFor(ruleId);
  let total = 0;

  for (let pass = 0; pass < MAX_FIX_PASSES; pass += 1) {
    const target = selected().filter((f) => f.ruleId === ruleId && canFix(f));
    if (target.length === 0) break;
    setStatus(`「${name}」を ${target.length} 件まとめて修正しています…`, true);
    const { applied, appliedFindings } = await actions.applyFindings(target, options());
    rememberFixed(appliedFindings);
    total += applied;
    current = await actions.reviewDocument(options());
    if (applied === 0) break;
  }

  renderReview();
  const remaining = selected().filter((f) => f.ruleId === ruleId && canFix(f)).length;
  if (total === 0) {
    setStatus(`「${name}」は修正できませんでした。もう一度［文書をチェック］を押してください。`);
    return;
  }
  setStatus(
    remaining === 0
      ? `「${name}」を ${total} 件まとめて修正しました。`
      : `「${name}」を ${total} 件修正しました。${remaining} 件は位置が変わったため残っています（もう一度押すと続けられます）。`,
  );
}

/** One finding's card. Inside a rule group the heading already names the rule. */
function findingRow(item: Finding, named = true): HTMLElement {
  const row = document.createElement("div");
  row.className = `finding severity-${item.severity}`;

  const head = document.createElement("div");
  head.className = "finding-head";

  if (named) {
    const badge = document.createElement("span");
    badge.className = "badge";
    badge.textContent = titleFor(item.ruleId);
    head.appendChild(badge);
  }

  const message = document.createElement("p");
  message.className = "finding-message";
  message.textContent = item.message;

  const quote = document.createElement("p");
  quote.className = "finding-quote";
  quote.textContent = `${where(item.paragraphIndex)}: ${truncate(item.matched, 60)}`;

  const buttons = document.createElement("div");
  buttons.className = "row compact";

  buttons.appendChild(
    button(
      "文書内で表示",
      run(async () => {
        const ok = await actions.revealFinding(item, options());
        setStatus(ok ? "該当箇所を選択しました。" : "該当箇所が見つかりませんでした。再度チェックしてください。");
      }),
    ),
  );

  if (canFix(item)) {
    buttons.appendChild(
      button(
        "修正",
        run(async () => {
          const { applied, appliedFindings } = await actions.applyFindings([item], options());
          if (applied === 0) {
            setStatus("修正できませんでした。もう一度チェックしてください。");
            return;
          }
          rememberFixed(appliedFindings);
          setStatus("修正しました。再点検します…");
          await runReview();
        }),
        "primary",
      ),
    );
  }

  buttons.appendChild(
    button(
      "コメント",
      run(async () => {
        const n = await actions.commentFindings([item], options());
        setStatus(n > 0 ? "この指摘をコメントとして挿入しました。" : "該当箇所が見つかりませんでした。");
      }),
    ),
  );
  buttons.appendChild(
    button(
      "マーカー",
      run(async () => {
        const n = await actions.highlightFindings([item], options());
        if (n > 0) remember([item]);
        setStatus(n > 0 ? "この指摘をマーカーで塗りました。" : "該当箇所が見つかりませんでした。");
      }),
    ),
  );

  buttons.appendChild(
    button("無視", () => {
      ignored.add(item);
      renderReview();
    }),
  );

  row.append(head, message, quote, buttons);
  return row;
}

/** A finding is fixable when it proposes text, or when it is a formatting check. */
function canFix(item: Finding): boolean {
  return item.replacement !== undefined || RULE_CATALOG.some((r) => r.id === item.ruleId && r.kind === "format");
}

function renderIgnored(): void {
  const container = byId("ignored");
  container.innerHTML = "";
  const items = ignored.entries();
  show("ignored-section", resultTab === "ignored");

  if (items.length === 0) {
    const empty = document.createElement("p");
    empty.className = "lead";
    empty.textContent = "無視した項目はありません。";
    container.appendChild(empty);
    return;
  }

  for (const { key, finding } of items) {
    const row = document.createElement("div");
    row.className = "finding ignored";

    const head = document.createElement("div");
    head.className = "finding-head";
    const badge = document.createElement("span");
    badge.className = "badge";
    badge.textContent = titleFor(finding.ruleId);
    head.appendChild(badge);

    const quote = document.createElement("p");
    quote.className = "finding-quote";
    quote.textContent = `${where(finding.paragraphIndex)}: ${truncate(finding.matched, 60)}`;

    const buttons = document.createElement("div");
    buttons.className = "row compact";
    buttons.appendChild(
      button("戻す", () => {
        ignored.remove(key);
        renderReview();
      }),
    );

    row.append(head, quote, buttons);
    container.appendChild(row);
  }
}

function rememberFixed(findings: readonly Finding[]): void {
  for (const finding of findings) {
    fixedRecords.push({
      finding,
      before: finding.matched,
      after: finding.replacement ?? "書式を修正",
    });
  }
}

function renderFixed(): void {
  const container = byId("fixed");
  container.innerHTML = "";
  show("fixed-section", resultTab === "fixed");

  if (fixedRecords.length === 0) {
    const empty = document.createElement("p");
    empty.className = "lead";
    empty.textContent = "このセッションで適用した修正はありません。";
    container.appendChild(empty);
    return;
  }

  for (const record of [...fixedRecords].reverse()) {
    const row = document.createElement("div");
    row.className = "finding fixed";
    const head = document.createElement("div");
    head.className = "finding-head";
    const badge = document.createElement("span");
    badge.className = "badge";
    badge.textContent = titleFor(record.finding.ruleId);
    head.appendChild(badge);
    const quote = document.createElement("p");
    quote.className = "finding-quote";
    quote.textContent =
      `${where(record.finding.paragraphIndex)}・文字 ${record.finding.start + 1}–${record.finding.end}：` +
      `${truncate(record.before, 36)} → ${truncate(record.after, 36)}`;
    row.append(head, quote);
    container.appendChild(row);
  }
}

/** The findings a ribbon command should act on: reviewed, not ignored, visible. */
function selected(): Finding[] {
  if (!current) return [];
  return ignored.filter(current.findings).filter((f) => visibleCategories.has(f.category));
}

async function highlightFindings(): Promise<void> {
  if (!current) {
    setStatus("先に［文書をチェック］を押してください。");
    return;
  }
  const target = selected();
  if (target.length === 0) {
    setStatus("塗る指摘がありません。");
    return;
  }
  setStatus("マーカーを塗っています…");
  const n = await actions.highlightFindings(target, options());
  remember(target);
  setStatus(`${n} 箇所をチェックリストの色で塗りました。片付けは［アドインの塗りを削除］。`);
}

async function commentFindings(): Promise<void> {
  if (!current) {
    setStatus("先に［文書をチェック］を押してください。");
    return;
  }
  const target = selected();
  if (target.length === 0) {
    setStatus("コメントにする指摘がありません。");
    return;
  }
  setStatus("コメントを挿入しています…", true);
  const n = await actions.commentFindings(target, options());
  setStatus(
    `${n} 件をコメントとして挿入しました。返信や解決は Word の校閲機能で行えます。片付けは［アドインのコメント削除］。`,
  );
}

async function clearComments(): Promise<void> {
  setStatus("このアドインが挿入したコメントを削除しています…", true);
  const n = await actions.clearComments(options());
  setStatus(
    n === 0
      ? "このアドインが挿入したコメントは見つかりませんでした（ほかの人のコメントは削除しません）。"
      : `${n} 件のコメントを削除しました（もとからあったコメントは残しています）。`,
  );
}

// --- 全部消す 2 つ ---------------------------------------------------------
//
// The destructive pair. Their siblings above undo only what this add-in did;
// these two take everything in scope, whoever put it there, and ⌘Z is the only
// way back. They are separate ribbon buttons rather than an option on the other
// two, so that erasing a co-author's markup is always something the user went
// and asked for by name.

async function clearAllComments(): Promise<void> {
  setStatus("文書のコメントをすべて削除しています…", true);
  const n = await actions.clearAllComments(options());
  setStatus(
    n === 0
      ? "コメントはありませんでした。"
      : `${n} 件のコメントをすべて削除しました（ほかの人のコメントも含みます。元に戻すのは ⌘Z）。`,
  );
}

async function clearAllHighlights(): Promise<void> {
  setStatus("文書のハイライトをすべて消去しています…", true);
  await actions.clearAllHighlights(options());
  painted = [];
  paintedSpaces = false;
  paintedFonts.clear();
  paintedCharacterStyles.clear();
  paintedCompoundLabels.clear();
  paintedReferenceMarkers.clear();
  paintedReferenceNumbers.clear();
  setStatus("文書のハイライトをすべて消去しました（手で塗ったマーカーも含みます。元に戻すのは ⌘Z）。");
}

// --- 化合物・文献・フォントの一覧 ------------------------------------------
//
// Views that answer 「この原稿には何が入っているのか」 rather than 「どこが間違って
// いるのか」. They share a shape: scan, list, click a row to jump.

/** Page numbers for the last list, when the host could supply them. */
let pageOf = new Map<number, number>();

/**
 * 「3ページ 12段落」 or just 「12段落」 where the host has no page API.
 *
 * For prose — status lines and tooltips, where the units make the sentence
 * read. Buttons want {@link whereShort} instead.
 */
function where(paragraphIndex: number): string {
  const page = pageOf.get(paragraphIndex);
  return page === undefined ? `${paragraphIndex + 1}段落` : `${page}ページ ${paragraphIndex + 1}段落`;
}

/**
 * 「p.3 ¶12」. The same place, for a button.
 *
 * 「7ページ 31段落」 spends half its width on the units, and eight of them wrap
 * to four lines in a 320px pane. The symbols are the ones the manuscript itself
 * uses, and the full Japanese stays on the button's tooltip and aria-label.
 */
function whereShort(paragraphIndex: number): string {
  const page = pageOf.get(paragraphIndex);
  return page === undefined ? `¶${paragraphIndex + 1}` : `p.${page} ¶${paragraphIndex + 1}`;
}

/** Compact page coverage for a grouped rule card. */
function pageRange(items: readonly Finding[]): string {
  const pages = [...new Set(items.map((item) => pageOf.get(item.paragraphIndex)).filter(
    (page): page is number => page !== undefined,
  ))].sort((a, b) => a - b);
  if (pages.length === 0) {
    const paragraphs = items.map((item) => item.paragraphIndex + 1).sort((a, b) => a - b);
    return `第 ${paragraphs[0]}–${paragraphs.at(-1)} 段落に出現`;
  }
  const first = pages[0]!;
  const last = pages.at(-1)!;
  return `p. ${first}${first === last ? "" : `–${last}`} に出現（${pages.length} ページ）`;
}

/**
 * 「文献 [6] を選択しました（62段落）。」 — どこへ飛んだかの一言。
 *
 * `name` は 「文献 [6]」「化合物 5a」「Figure 1」 のように、それだけで読めるもの
 * を呼び出し側が渡す。以前はここが 「「[6]」1/1 件目（62段落）を選択しました。」
 * で、22 字のうち 6 字が括弧だった。鉤括弧は 「[6]」 が名前であることを示すために
 * 足したものだが、頭に 「文献」 と付ければ何の番号かは括弧なしで伝わる。
 *
 * 1 件しかない番号に 「1/1 件目」 と言うのも、数えるものが無いのに数えている。
 * 何件目かは 2 件以上あるときだけ言う。
 */
async function reveal(
  name: string,
  occurrence: actions.Occurrence,
  index: number,
  total: number,
): Promise<void> {
  const ok = await actions.revealSpan(
    { paragraphIndex: occurrence.paragraphIndex, start: occurrence.start, matched: occurrence.text },
    options(),
  );
  // 「[6]」 のうしろに 「を」 を直に付けると括弧と字がくっついて読みにくいが、
  // 「件目」 のうしろは空けたくない。助詞まで含めてここで組む。
  const what = total > 1 ? `${name} の ${index + 1} 件目を` : `${name} を`;
  setStatus(
    ok
      ? `${what}選択しました（${where(occurrence.paragraphIndex)}）。`
      : "該当箇所が見つかりませんでした。文書が変わっている場合は一覧を作り直してください。",
  );
}

/** 場所ボタンの説明。1 箇所しかなければ何件目かは言わない（{@link reveal} と同じ）。 */
function placeTitle(name: string, index: number, total: number, paragraphIndex: number): string {
  const which = total > 1 ? `${name} の ${index + 1} 件目` : name;
  return `${which}（${where(paragraphIndex)}）へ移動`;
}

/**
 * 出現箇所を 1 つずつ押せる行。ページごとに束ねる。
 *
 * The locations used to be plain text, which meant the only way to reach the
 * fourth mention of a compound was to press the label three times and watch the
 * cursor go by. Each place is its own button now, so 「p.7 ¶31」 is a
 * destination rather than a description.
 *
 * Repeating the page on every button wastes the width and hides the shape of
 * the answer, so consecutive mentions on one page share a 「p.7」 in the margin
 * and the buttons carry only the paragraph. Runs are consecutive rather than
 * merged: the occurrences arrive in document order and should stay that way.
 * Where the host has no page API there is one unlabelled run, which lands back
 * on the flat row this used to be.
 */
function placesRow(
  name: string,
  occurrences: readonly actions.Occurrence[],
  onChoose?: () => void,
): HTMLElement {
  const row = document.createElement("div");
  row.className = "finding-quote places";
  const runs: { page: number | undefined; at: number[] }[] = [];
  occurrences.forEach((occurrence, i) => {
    const page = pageOf.get(occurrence.paragraphIndex);
    const open = runs.at(-1);
    if (open && open.page === page) open.at.push(i);
    else runs.push({ page, at: [i] });
  });
  for (const { page, at } of runs) {
    const line = document.createElement("div");
    line.className = "places-line";
    if (page !== undefined) {
      const pageLabel = document.createElement("span");
      pageLabel.className = "place-page";
      pageLabel.textContent = `p.${page}`;
      line.appendChild(pageLabel);
    }
    for (const i of at) {
      const occurrence = occurrences[i]!;
      const place = document.createElement("button");
      place.type = "button";
      place.className = "place";
      place.textContent = `¶${occurrence.paragraphIndex + 1}`;
      place.title = placeTitle(name, i, occurrences.length, occurrence.paragraphIndex);
      place.setAttribute("aria-label", place.title);
      place.onclick = run(async () => {
        onChoose?.();
        await reveal(name, occurrence, i, occurrences.length);
      });
      line.appendChild(place);
    }
    row.appendChild(line);
  }
  return row;
}

/**
 * 化合物番号の一覧。
 *
 * A table rather than the chips it used to be: with the page and paragraph of
 * every mention there is too much to fit on one line, and 「何ページの何段落」 is
 * the thing that makes the list usable without clicking each row.
 */
function renderCompounds(items: readonly actions.InventoryItem[]): void {
  const container = byId("compounds");
  setSectionCount("count-compounds", `${items.length} 種類`);
  container.innerHTML = "";
  const highlightSelect = byId("compound-highlight-select") as HTMLSelectElement;
  const previousHighlight = highlightSelect.value;
  highlightSelect.innerHTML = "";
  for (const item of items) {
    const option = document.createElement("option");
    option.value = item.label;
    option.textContent = `${item.label}（${item.occurrences.length} 件）`;
    highlightSelect.appendChild(option);
  }
  if ([...highlightSelect.options].some((option) => option.value === previousHighlight)) {
    highlightSelect.value = previousHighlight;
  }
  if (items.length === 0) {
    const empty = document.createElement("p");
    empty.className = "lead";
    empty.textContent =
      "化合物番号は見つかりませんでした（太字の番号、「化合物 5」のように語を伴うもの、5a のような系列ラベルを数えます）。";
    container.appendChild(empty);
    return;
  }

  for (const item of items) {
    const row = document.createElement("details");
    row.className = "compound-item";
    const head = document.createElement("summary");
    const toggle = document.createElement("span");
    toggle.className = "compound-toggle";
    const label = document.createElement("strong");
    label.className = "compound-label";
    label.textContent = item.label;
    const count = document.createElement("span");
    count.className = "compound-count";
    count.textContent = `${item.occurrences.length} 件`;
    const meta = document.createElement("span");
    meta.className = "compound-meta";
    meta.append(label, count);
    const thumbnail = document.createElement("img");
    thumbnail.className = "compound-thumbnail";
    thumbnail.dataset.compoundLabel = item.label;
    thumbnail.alt = `化合物 ${item.label} の登録画像`;
    const image = compoundNotes.get(item.label)?.image;
    thumbnail.src = image ?? "";
    thumbnail.hidden = image === undefined;
    row.classList.toggle("has-thumbnail", image !== undefined);
    toggle.append(thumbnail, meta);
    head.append(toggle);
    const detail = document.createElement("div");
    detail.className = "compound-detail";
    const locations = document.createElement("section");
    locations.className = "compound-detail-section";
    const locationsHeading = document.createElement("p");
    locationsHeading.className = "compound-detail-heading";
    locationsHeading.textContent = "出現箇所";
    // The buttons below say 「p.7 ¶31」; this is where the units get explained.
    const legend = document.createElement("span");
    legend.className = "places-legend";
    legend.textContent = "p. ページ / ¶ 段落";
    locationsHeading.appendChild(legend);
    locations.append(locationsHeading, placesRow(`化合物 ${item.label}`, item.occurrences));
    detail.append(locations, compoundNoteEditor(item.label));
    row.append(head, detail);
    row.addEventListener("toggle", () => {
      if (!row.open) return;
      for (const other of container.querySelectorAll<HTMLDetailsElement>(".compound-item[open]")) {
        if (other !== row) other.open = false;
      }
    });
    container.appendChild(row);
  }
}

/**
 * 直すべき印と、確かめるだけの印.
 *
 * 3 つの印を同じ琥珀で並べていたので、どれも同じ重さに見えていた。ところが
 * 「キャプションなし」 は原稿の誤りとは限らない —— キャプションが図の中に画像
 * として入っていれば、正しく書けていても必ずこう出る（帯にもそう書いてある）。
 * 残る 2 つは原稿の側の話で、見つけたら直すものになる。
 *
 * そこで、直すものだけを琥珀にし、確かめるだけのものは灰にする。数が減るのでは
 * なく、目に入る順番が変わる。
 */
const FIGURE_ISSUES_TO_FIX: ReadonlySet<string> = new Set([
  "本文で参照なし",
  "キャプションが 2 つ以上",
  // 番号の抜け。`figureTableIssues` は出す番号についてしか言えないので、これだけは
  // 行を組み立てる側（抜けの行）が渡してくる。
  "見つかりません",
]);

/** 印 1 枚。直すものは琥珀、確かめるだけのものは灰。 */
function figureFlag(issue: string): HTMLElement {
  const flag = document.createElement("span");
  flag.className = FIGURE_ISSUES_TO_FIX.has(issue) ? "figure-flag warn" : "figure-flag";
  flag.textContent = issue;
  return flag;
}

/** 番号ごとの場所ボタン。キャプションと本文参照は同じ行で色分けする。 */
function figurePlaces(item: actions.FigureTableItem): HTMLElement {
  const places = document.createElement("span");
  places.className = "figure-places";
  const total = item.captions.length + item.references.length;
  const add = (occurrences: readonly actions.Occurrence[], name: string, offset: number) => {
    if (occurrences.length === 0) return;
    const tag = document.createElement("span");
    tag.className = "figure-places-label";
    tag.textContent = name;
    places.appendChild(tag);
    occurrences.forEach((occurrence, i) => {
      const place = button(whereShort(occurrence.paragraphIndex), run(async () => {
        await reveal(item.label, occurrence, offset + i, total);
      }), `place${name === "キャプション" ? " caption" : ""}`);
      place.title = `${item.label} の${name}（${where(occurrence.paragraphIndex)}）へ移動`;
      place.setAttribute("aria-label", place.title);
      places.appendChild(place);
    });
  };
  add(item.captions, "キャプション", 0);
  add(item.references, "本文", item.captions.length);
  return places;
}

/**
 * カードを押したときの開け閉め。文献一覧と図・表一覧が同じ規則で動く.
 *
 * 押したものが開いていれば閉じる。閉じていれば開き、［1 枚ずつ開く］のときだけ
 * その前に他を閉じる。［すべて開く］はここを通っても畳めない —— 描く側が
 * 無条件に開くので、押しても何も起きないのが正しい。
 *
 * 戻り値は、そのカードが開いた状態になったかどうか。呼ぶ側は「選択中の 1 枚」を
 * これで決める。
 */
function toggleCard<T>(open: Set<T>, key: T, mode: CardExpand): boolean {
  if (open.delete(key)) return false;
  if (mode === "one") open.clear();
  open.add(key);
  return true;
}

/** 押したカードを開け閉めする。文献一覧の `selectReference` と同じ役目。 */
function selectFigure(label: string): void {
  toggleCard(openFigures, label, prefs.figureExpand);
  renderFigures(lastFigures);
}

/**
 * 図表番号の一覧。文献一覧と同じ 1 件 1 枚のカード.
 *
 * かつて化合物カードを流用したときは、短い番号を格子に詰める作りだったので
 * 「Figure 1 キャプション 0 件／本文 1 件」が幅に入らず、毎行が全幅に伸びていた。
 * そのあと素の行に直したが、こんどは**その番号が何の図なのかが一言も出ない**
 * 一覧になった —— 並んでいるのは番号と居場所だけで、Figure 3 と Figure 6 の
 * どちらを見に行くべきかは、結局どちらも開いてみないと分からない。
 *
 * 文献カードは同じ問題をすでに解いている。畳んだ 1 枚に「番号・その 1 件が何か
 * （書誌）・回数」を 1 行で並べ、押した 1 枚だけが場所を開く。図表でその「何か」に
 * 当たるのはキャプション本文なので、同じ形をそのまま使う。左の色は文献と同じ
 * 意味で、赤が直すもの、灰が確かめるだけのもの。
 */
function renderFigures(items: readonly actions.FigureTableItem[]): void {
  const container = byId("figures");
  container.innerHTML = "";
  show("figure-tools", items.length > 0);
  show("figure-settings-wrap", items.length > 0);
  if (items.length === 0) {
    const empty = document.createElement("p");
    empty.className = "lead";
    empty.textContent = "Figure、Table、Scheme、Chart、Equation や 図・表・スキーム の番号は見つかりませんでした。";
    container.appendChild(empty);
    return;
  }

  const issuesOf = new Map(items.map((item) => [item.label, figureTableIssues(item)]));
  const flagged = items.filter((item) => (issuesOf.get(item.label) ?? []).length > 0);
  const missing = missingFigureNumbers(items);
  const outOfOrder = figuresOutOfOrder(items);

  // 全件に付く印は行から外す。7 行に同じ札が並べば、それは「キャプション 0 件」が
  // 7 回並んでいた元の一覧と同じ読みにくさで、上の 1 行がすでに同じことを言っている。
  const universal = new Set(
    [...new Set([...issuesOf.values()].flat())].filter(
      (issue) => items.every((item) => (issuesOf.get(item.label) ?? []).includes(issue)),
    ),
  );

  const filterAll = byId("figure-filter-all");
  const filterIssue = byId("figure-filter-issue");
  filterAll.textContent = `すべて ${items.length}`;
  filterIssue.textContent = `問題あり ${flagged.length}`;
  filterIssue.hidden = flagged.length === 0 || flagged.length === items.length;
  if (filterIssue.hidden) figureFilter = "all";
  filterAll.setAttribute("aria-pressed", String(figureFilter === "all"));
  filterIssue.setAttribute("aria-pressed", String(figureFilter === "issue"));
  // 並べ替えが行を動かすのは、初出が番号順と食い違っているときだけ。順序どおりの
  // 原稿では押しても無反応で、それは「効かないボタン」としか読めない。帯が乱れを
  // 告げたときにだけ出せば、そこを見に行くための道具だと分かる。
  const sort = byId("figure-sort");
  sort.hidden = !outOfOrder;
  if (sort.hidden) figureSort = "number";
  sort.setAttribute("aria-pressed", String(figureSort === "appearance"));

  const shown = figureFilter === "issue" ? flagged : items;
  // 0 件の種類は見出しごと出さない。「Table 0 種」の空欄は場所を取るだけで、
  // 表がない原稿ではそれが正常。
  for (const kind of FIGURE_KINDS) {
    const group = shown.filter((item) => item.kind === kind);
    if (group.length === 0) continue;
    const sorted = [...group].sort((a, b) =>
      figureSort === "appearance" ? figureFirstAt(a) - figureFirstAt(b) : a.number - b.number,
    );

    const section = document.createElement("details");
    section.className = "figure-group";
    section.open = !figureCollapsed.has(kind);
    section.ontoggle = () => {
      if (section.open) figureCollapsed.delete(kind);
      else figureCollapsed.add(kind);
    };
    const head = document.createElement("summary");
    const name = document.createElement("span");
    name.textContent = kind;
    const count = document.createElement("span");
    // フォント一覧の節と同じ件数表示。畳んだままでも中身の量が分かる。
    count.className = "section-count";
    const mentions = group.reduce((total, item) => total + item.captions.length + item.references.length, 0);
    count.textContent = `${group.length} 種類・${mentions} 箇所`;
    head.append(name, count);
    section.appendChild(head);

    for (const item of sorted) {
      // 抜けている番号は、本来そこにあるはずの位置に差し込む。並べ替えているときは
      // その位置が意味を持たないので、上の 1 行だけに任せる。
      if (figureSort === "number") {
        for (const gap of missing.filter((entry) => entry.kind === kind && entry.number < item.number)) {
          if (section.querySelector(`[data-gap="${gap.label}"]`)) continue;
          section.appendChild(missingFigureCard(gap.label));
        }
      }

      const issues = (issuesOf.get(item.label) ?? []).filter((issue) => !universal.has(issue));
      section.appendChild(figureCard(item, issues));
    }
    container.appendChild(section);
  }
}

/**
 * 図表 1 件のカード。
 *
 * 畳んだ 1 枚は 1 行 ——「番号・キャプション本文・参照回数」。開くと印と場所が
 * 続く。文献カード（`renderReferences`）と同じ組み立てで、`finding` の枠と
 * `severity` の札もそのまま使う。同じ姿のものを 2 通りに書けば、片方だけが
 * 直らなくなる。
 */
function figureCard(item: actions.FigureTableItem, issues: readonly string[]): HTMLElement {
  const toFix = issues.some((issue) => FIGURE_ISSUES_TO_FIX.has(issue));
  const open = prefs.figureExpand === "all" || openFigures.has(item.label);
  const card = document.createElement("article");
  card.className = `finding figure-item ${toFix ? "severity-fix" : "severity-note"}`;
  card.classList.toggle("selected", open);
  card.classList.toggle("collapsed", !open);
  card.title = open ? "" : `押すと、${item.label} の場所を開きます。`;
  card.onclick = (event) => {
    if ((event.target as HTMLElement).closest("button, a, input, select, label")) return;
    selectFigure(item.label);
  };

  const line = document.createElement("div");
  line.className = "reference-line";
  const text = document.createElement("p");
  text.className = "finding-message reference-entry";
  const label = document.createElement("span");
  label.className = "reference-number";
  label.textContent = item.label;
  text.appendChild(label);
  // キャプションが取れていないときに空白を置くと、番号だけの行が何行も続いて
  // 「まだ読み込み中なのか」に見える。取れなかったことをその場で言う。
  if (item.captionText.length > 0) {
    text.title = `${item.label}. ${item.captionText}`;
    text.append(item.captionText);
  } else {
    const none = document.createElement("span");
    none.className = "figure-caption-missing";
    none.textContent = "キャプションの文が見つかりません";
    text.appendChild(none);
  }

  line.appendChild(text);
  // 0 回のときに札を出さないのは、そのカードには必ず「本文で参照なし」の印が
  // 付くから。同じことを 1 行のうちに 2 度言うと、どちらかが別の話に見える。
  if (item.references.length > 0) {
    const count = document.createElement("span");
    count.className = "severity";
    count.textContent = `${item.references.length} 回`;
    count.title = "本文がこの番号に触れている回数（キャプションは数えません）";
    line.appendChild(count);
  }
  card.appendChild(line);

  // 畳んだ分は組み立てない。文献カードと同じ理由で、隠すだけでは軽くならない。
  if (open) {
    if (issues.length > 0) {
      const flags = document.createElement("div");
      flags.className = "figure-flags";
      for (const issue of issues) flags.appendChild(figureFlag(issue));
      card.appendChild(flags);
    }
    card.appendChild(figurePlaces(item));
  } else if (issues.length > 0) {
    // 畳んでいても印は出す。開かないと分からない印では、番号の多い原稿で
    // 探す役に立たない（文献カードの「要確認」と同じ）。
    const flags = document.createElement("div");
    flags.className = "figure-flags collapsed-flags";
    for (const issue of issues) flags.appendChild(figureFlag(issue));
    card.appendChild(flags);
  }
  return card;
}

/** 抜けている番号のカード。飛び先が無いので、畳み開きもしない。 */
function missingFigureCard(label: string): HTMLElement {
  const card = document.createElement("article");
  card.className = "finding figure-item figure-item-missing severity-fix collapsed";
  card.dataset.gap = label;

  const line = document.createElement("div");
  line.className = "reference-line";
  const text = document.createElement("p");
  text.className = "finding-message reference-entry";
  const number = document.createElement("span");
  number.className = "reference-number";
  number.textContent = label;
  text.append(number, "この番号は原稿のどこにもありません");
  const flag = figureFlag("見つかりません");
  line.append(text, flag);
  card.appendChild(line);
  return card;
}

/**
 * 印の名前と、それを文にしたときの言い方.
 *
 * カードの上では「本文で参照なし」でよい —— 何の話かは、その札が付いている
 * カードが言っている。一覧の外に出した 1 行にはそれが無いので、何が 5 件なのかを
 * 言葉のほうが持たなければならない（「本文で参照なし 5 件」では、5 件が図なのか
 * 参照なのかが決まらない）。
 */
const FIGURE_ISSUE_SENTENCES: Readonly<Record<string, string>> = {
  "本文で参照なし": "本文で参照されていない図・表",
  "キャプションなし": "キャプションの文が見つからない図・表",
  "キャプションが 2 つ以上": "キャプションが 2 つ以上ある図・表",
};

/**
 * 数えた結果に続ける、引っかかりの文.
 *
 * 以前はこれを琥珀の帯にしてタイトルの下へ置いていた。「本文で参照なし 5 件。」
 * の 1 文が、それが指している一覧そのものより目立っていて、順番が逆だった。
 * 文献一覧（`referenceNotes`）と同じで、数えた 1 行に続けて書けば足りる。
 */
function figureNotes(items: readonly actions.FigureTableItem[]): string[] {
  const counts = new Map<string, number>();
  for (const item of items) {
    for (const issue of figureTableIssues(item)) counts.set(issue, (counts.get(issue) ?? 0) + 1);
  }

  const notes = [...counts].map(([issue, count]) => {
    const all = count === items.length && items.length > 1 ? "（すべて）" : "";
    return `${FIGURE_ISSUE_SENTENCES[issue] ?? issue}が ${count} 件${all}あります。`;
  });

  const missing = missingFigureNumbers(items);
  if (missing.length > 0) {
    notes.push(`${numberList(missing.map((entry) => entry.label))} が見つかりません。`);
  }
  if (figuresOutOfOrder(items)) notes.push("本文に出てくる順が番号順と違います。");

  // キャプションが 1 つも取れないときは、原稿ではなく検出側の限界であることが多い。
  if (counts.get("キャプションなし") === items.length) {
    notes.push("キャプションが図の中に画像として入っている場合や、テキストボックス内にある場合は検出できません。");
  }
  return notes;
}

/**
 * 押したときだけ出る小窓。開閉と、外を押したとき・Esc で閉じる分.
 *
 * パネルには 3 つある —— 更新の知らせ、検索、文献一覧の設定。同じ振る舞いを
 * 3 度書けば、そのうち 1 つだけ Esc で閉じない、が必ず起きる。
 *
 * `insideSummary` は `<summary>` の中に置く小窓のため。押した出来事を止めないと
 * `<details>` が畳み開きし、開いたばかりの小窓ごと消える。
 */
function setUpPopover(
  toggleId: string,
  popoverId: string,
  options: { readonly insideSummary?: boolean; readonly onOpen?: () => void } = {},
): { readonly close: () => void } {
  const toggle = byId(toggleId) as HTMLButtonElement;
  const popover = byId(popoverId);

  const close = (): void => {
    popover.hidden = true;
    toggle.setAttribute("aria-expanded", "false");
  };

  toggle.onclick = (event) => {
    if (options.insideSummary) {
      event.preventDefault();
      event.stopPropagation();
    }
    const opening = popover.hidden;
    popover.hidden = !opening;
    toggle.setAttribute("aria-expanded", String(opening));
    if (opening) options.onOpen?.();
  };
  // 小窓の中身は入力欄なので、押しても見出しには渡さない。
  if (options.insideSummary) popover.onclick = (event) => event.stopPropagation();

  document.addEventListener("click", (event) => {
    if (popover.hidden) return;
    const target = event.target as Node;
    if (toggle.contains(target) || popover.contains(target)) return;
    close();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !popover.hidden) close();
  });
  return { close };
}

/** 検索の 4 欄。空欄は条件にならない。 */
interface ReferenceQuery {
  readonly number: string;
  readonly author: string;
  readonly journal: string;
  readonly year: string;
}

const SEARCH_FIELDS: Readonly<Record<keyof ReferenceQuery, string>> = {
  number: "reference-search-number",
  author: "reference-search-author",
  journal: "reference-search-journal",
  year: "reference-search-year",
};

function referenceQuery(): ReferenceQuery {
  const value = (key: keyof ReferenceQuery): string =>
    (byId(SEARCH_FIELDS[key]) as HTMLInputElement).value.trim();
  return { number: value("number"), author: value("author"), journal: value("journal"), year: value("year") };
}

/**
 * 4 欄すべてに当たるか（欄どうしも AND）。
 *
 * 番号だけは**完全一致**。番号の欄に 1 と入れて [1] [10] [11] [12]… が並ぶのは、
 * 番号で引く人の期待と違う。
 *
 * 著者・誌名・年は、書誌を割った欄の中を探す（`entrySegments`）。**割れなかった
 * 書誌は、行全体を相手に探す** —— 形が読めなかっただけの項目が検索から消えると、
 * 探している当人には「無い」としか見えない。
 */
function matchesQuery(item: actions.ReferenceRow, query: ReferenceQuery): boolean {
  if (query.number.length > 0 && String(item.number) !== query.number) return false;

  const full = item.entry?.full ?? "";
  const parts = entrySegments(full);
  const inField = (field: string, term: string): boolean =>
    term.length === 0 || matchesAllTerms(field.length > 0 ? field : full, searchTerms(term));

  return inField(parts.authors, query.author)
    && inField(parts.journal, query.journal)
    && inField(parts.year, query.year);
}

/**
 * 検索を、押したときだけ出す小窓にする.
 *
 * これは畳んだ節として一覧の上にあった。畳んでいても見出しは残るので、
 * ［文献］を開いた人が最初に読むのが 「検索・絞り込み」 という、文献の話ではない
 * 一行になっていた。虫眼鏡なら、探したい人にだけ見える。
 */
function setUpReferenceSearch(): void {
  setUpPopover("reference-search-toggle", "reference-search-popover", {
    insideSummary: true,
    onOpen: () => (byId(SEARCH_FIELDS.number) as HTMLInputElement).focus(),
  });
}

/**
 * 文献一覧の見え方 —— タイトル行の歯車.
 *
 * 「著者を何人出すか」「Crossref に問い合わせるか」「カードを 1 枚ずつ開くか」は
 * 探すための道具ではなく好みなので、虫眼鏡から分けてここに移した。3 つとも
 * `prefs` に入れて保存する —— 開き直すたび既定へ戻る設定は、覚えていないほうが
 * 不親切になる（とくに Crossref は、押し直すたびに 2 分かかる）。
 */
function setUpReferenceSettings(redraw: () => void): void {
  setUpPopover("reference-settings-toggle", "reference-settings-popover");

  const authors = byId("reference-authors") as HTMLSelectElement;
  const expand = byId("reference-expand") as HTMLSelectElement;
  const wrap = byId("reference-wrap") as HTMLSelectElement;
  const crossref = byId("crossref-enabled") as HTMLInputElement;
  authors.value = prefs.referenceAuthors;
  expand.value = prefs.referenceExpand;
  wrap.value = prefs.referenceWrap;
  crossref.checked = prefs.referenceCrossref;

  const save = (patch: Partial<Preferences>): void => {
    prefs = { ...prefs, ...patch };
    savePreferences(prefs);
  };

  authors.onchange = () => {
    save({ referenceAuthors: authors.value === "all" ? "all" : "short" });
    redraw();
  };
  expand.onchange = () => {
    save({ referenceExpand: cardExpand(expand.value) });
    keepOneOpen(openReferences, prefs.referenceExpand, selectedReferenceNumber);
    redraw();
  };
  wrap.onchange = () => {
    save({ referenceWrap: wrap.value === "wrap" ? "wrap" : "clip" });
    redraw();
  };
  crossref.onchange = () => {
    save({ referenceCrossref: crossref.checked });
    if (!lastLabels) return;
    renderReferences(lastLabels);
    if (crossref.checked) void enrichReferences(lastLabels);
  };
}

/**
 * ［1 枚ずつ開く］へ切り替えたとき、開きすぎている分を畳む.
 *
 * ［選んだものを開く］で 5 枚開いてから切り替えると、そのままでは 5 枚とも
 * 開いたままになる。選んだ規則と目の前の一覧が食い違うので、最後に選んだ 1 枚
 * だけ残す。何も選んでいなければ全部畳む。
 */
function keepOneOpen<T>(open: Set<T>, mode: CardExpand, keep: T | null): void {
  if (mode !== "one" || open.size <= 1) return;
  open.clear();
  if (keep !== null) open.add(keep);
}

/** ［図・表］の歯車。中身はカードの開き方 1 つだけ。 */
function setUpFigureSettings(): void {
  setUpPopover("figure-settings-toggle", "figure-settings-popover");
  const expand = byId("figure-expand") as HTMLSelectElement;
  expand.value = prefs.figureExpand;
  expand.onchange = () => {
    prefs = { ...prefs, figureExpand: cardExpand(expand.value) };
    savePreferences(prefs);
    // 図表には「選択中の 1 枚」が無いので、残すのは開いている中の先頭。
    keepOneOpen(openFigures, prefs.figureExpand, [...openFigures][0] ?? null);
    renderFigures(lastFigures);
  };
}

/**
 * 出現箇所を、図・表の一覧と同じ 1 本の折り返し行にする。
 *
 * `placesRow` はページごとに改行し、左端に 「p.15」 の欄を立てる。化合物のように
 * 同じページへ何度も出るものはそれで読めるが、文献の引用は 1 ページに 1 回ずつ
 * ばらけることが多く、**1 件の引用に 1 行**を使ってしまう。5 回引かれた文献が
 * 縦に 4 行、それが 99 件では一覧にならない。
 *
 * 図・表の `figure-places` はこれを 「p.3 ¶62」 のボタンを並べて折り返すだけで
 * 済ませている。同じ画面の中に読み方の違う場所の書き方が 2 つある理由も無い。
 */
function placesLine(
  name: string,
  occurrences: readonly actions.Occurrence[],
  onChoose?: () => void,
): HTMLElement {
  const row = document.createElement("span");
  row.className = "figure-places";
  occurrences.forEach((occurrence, i) => {
    const place = button(whereShort(occurrence.paragraphIndex), run(async () => {
      onChoose?.();
      await reveal(name, occurrence, i, occurrences.length);
    }), "place");
    place.title = placeTitle(name, i, occurrences.length, occurrence.paragraphIndex);
    place.setAttribute("aria-label", place.title);
    row.appendChild(place);
  });
  return row;
}

/**
 * Selects a citation without making the number button compete with location buttons.
 *
 * もう一度押せば閉じる。開けたものを閉じられないと、開いた 1 枚が一覧の残りを
 * 押しのけたまま残る。閉じたときの［文献リストへ移動］は [1] を指す（`renderReferences`
 * の `target`）—— 選ぶ前と同じで、押せなくなるわけではない。
 */
function selectReference(number: number): void {
  const opened = toggleCard(openReferences, number, prefs.referenceExpand);
  selectedReferenceNumber = opened ? number : null;
  if (lastLabels) renderReferences(lastLabels);
}

/** The sole route from the pane into the bibliography entry. */
async function jumpToSelectedReference(): Promise<void> {
  const item = lastLabels?.references.find((reference) => reference.number === (selectedReferenceNumber ?? 1));
  if (!item?.entry) {
    setStatus("文献 [1] が文献リストに見つかりません。文献カードを選んでください。");
    return;
  }
  setStatus("本文中の文献リストへ移動しています…", true);
  const ok = await actions.revealBibliographyEntry(item.entry.at.text, item.entry.full);
  setStatus(
    ok
      ? `本文中の文献リスト（${where(item.entry.at.paragraphIndex)}）へ移動しました。`
      : "文献リストの項目が見つかりませんでした。一覧を作り直してください。",
  );
}

/** Where the author string ends in the common author–journal–year layout. */
function authorEnd(text: string): number | null {
  const yearAt = text.search(/(?:19|20)\d{2}\s*,\s*\d+/u);
  if (yearAt < 0) return null;
  const head = text.slice(0, yearAt);
  const etAl = /\bet\s+al\.?\s*/iu.exec(head);
  if (etAl) return etAl.index + etAl[0].length;
  const at = Math.max(head.lastIndexOf(","), head.lastIndexOf(";"));
  if (at < 0) return null;
  let end = at + 1;
  // In "Smith, J.; Brown, K. Chem. Commun.", the last comma lands before
  // K.; include that final initial but not the journal name.
  if (head.includes(",")) {
    const trailingInitial = /^\s*[A-Z]\.\s+(?=[A-Z])/u.exec(head.slice(end));
    if (trailingInitial) end += trailingInitial[0].length;
  }
  return end;
}

const FIRST_AUTHOR = /^([A-Z][A-Za-z'’-]+(?:,\s*[A-Z]\.(?:\s*[A-Z]\.)*)?|(?:[A-Z]\.\s*)+[A-Z][A-Za-z'’-]+)/u;
const REFERENCE_LINK = /(https?:\/\/[^\s<>]+|\bdoi:\s*(10\.\d{4,9}\/[\w.()/:;-]+)|\b(10\.\d{4,9}\/[\w.()/:;-]+))/giu;

/** Appends text, promoting URLs and DOI strings to usable external links. */
function appendLinkedText(parent: HTMLElement, text: string): void {
  let from = 0;
  for (const match of text.matchAll(REFERENCE_LINK)) {
    const at = match.index ?? 0;
    parent.append(document.createTextNode(text.slice(from, at)));
    const displayed = match[0];
    const doi = match[2] ?? match[3];
    const link = document.createElement("a");
    link.href = doi ? `https://doi.org/${doi}` : displayed;
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.textContent = displayed;
    link.title = doi ? "DOI を開く" : "URL を開く";
    parent.append(link);
    from = at + displayed.length;
  }
  parent.append(document.createTextNode(text.slice(from)));
}

/** Source bold/italic is retained even when the author list is abbreviated. */
function appendReferenceText(
  parent: HTMLElement,
  entry: NonNullable<actions.ReferenceRow["entry"]>,
  authors: "short" | "all",
): void {
  const candidateEnd = authors === "short" ? authorEnd(entry.full) : null;
  const end = candidateEnd !== null && !/\bet\s+al\.?\s*$/iu.test(entry.full.slice(0, candidateEnd))
    ? candidateEnd
    : null;
  const first = FIRST_AUTHOR.exec(entry.full)?.[1];
  if (end !== null && first) {
    appendLinkedText(parent, `${first} `);
    // 「et al.」 はラテン語の略で、斜体で組む。読点は著者と誌名の切れ目 ——
    // 「B. Shan et al., Tetrahedron Lett.」。斜体にするのは略語だけで、
    // 読点まで斜体にすると誌名にかかっているように見える。
    const etAl = document.createElement("span");
    etAl.className = "reference-italic";
    etAl.textContent = "et al.";
    parent.append(etAl);
    // 原文が 「et al., 誌名」 だったときは読点ごと残っている。足すと 2 つ並ぶ。
    parent.append(document.createTextNode(/^\s*[,;、，]/u.test(entry.full.slice(end)) ? "" : ", "));
  }
  let offset = 0;
  for (const run of entry.formatting) {
    const runStart = offset;
    offset += run.text.length;
    const start = end === null ? 0 : Math.max(0, end - runStart);
    if (start >= run.text.length) continue;
    const styled = document.createElement("span");
    styled.className = `${run.bold ? "reference-bold " : ""}${run.italic ? "reference-italic" : ""}`.trim();
    appendLinkedText(styled, run.text.slice(start));
    parent.append(styled);
  }
}

function stringField(source: unknown, key: string): string | undefined {
  if (source === null || typeof source !== "object") return undefined;
  const value = (source as Record<string, unknown>)[key];
  return typeof value === "string" && value.trim().length > 0 ? value.trim() : undefined;
}

function firstStringField(source: unknown, key: string): string | undefined {
  if (source === null || typeof source !== "object") return undefined;
  const value = (source as Record<string, unknown>)[key];
  return Array.isArray(value) && typeof value[0] === "string" && value[0].trim().length > 0
    ? value[0].trim()
    : undefined;
}

// --- Crossref の速度制限 ---------------------------------------------------
//
// 公開プール（mailto を名乗らない利用者）に許されているのは **1 秒に 1 件、
// 同時 1 本** で、サーバー自身が毎回そう答えている：
//
//     x-rate-limit-limit: 1   x-rate-limit-interval: 1s   x-concurrency-limit: 1
//
// 以前は 3 本並列で投げていたので、最初の 3 件が通ったあとは全部 429 になり、
// しかも 429 は「取得できなかった」として何も描かなかった。99 件の原稿で
// 「最初の 3 件しか出ない」という形で表に出た —— 制限の話だとは誰も分からない。
//
// そこで、投げるのは 1 本ずつ、間隔はサーバーの答えたとおりに空ける。

/**
 * 制限が読めなかったときの間隔。
 *
 * 公開プールの公称は 1 秒に 1 件。ちょうど 1 秒だと 429 が混ざるので 1 割足す
 * （実測：1.1 秒間隔なら 12 件連続で通り、0.6 秒では 8 件中 2 件が 429）。
 * ヘッダは CORS 次第で読めないことがあるため、この既定値が実際の速度になる。
 */
const CROSSREF_GAP_MS = 1100;
/** 429 のときの待ち。3 回まで、倍々で。 */
const CROSSREF_RETRIES = 3;

/** 次に投げてよい時刻（ミリ秒）。1 本ずつなので、これだけで足りる。 */
let crossrefNextAt = 0;
/** サーバーが答えた 1 件あたりの間隔。 */
let crossrefGapMs = CROSSREF_GAP_MS;

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => window.setTimeout(resolve, Math.max(0, ms)));
}

/** 「x-rate-limit-limit: 3」「…-interval: 1s」から 1 件あたりの間隔を得る。 */
function crossrefGapFrom(response: Response): number {
  const limit = Number(response.headers.get("x-rate-limit-limit"));
  const interval = /^(\d+)s$/u.exec(response.headers.get("x-rate-limit-interval") ?? "");
  if (!Number.isFinite(limit) || limit < 1 || !interval) return crossrefGapMs;
  // 制限ちょうどでは 429 が出るので、1 割の余裕を持たせる。
  return Math.min(5000, Math.max(200, Math.ceil((Number(interval[1]) * 1000 * 1.1) / limit)));
}

/** Fetches the best bibliographic match; Crossref ranks query results by relevance. */
async function lookupCrossref(entry: NonNullable<actions.ReferenceRow["entry"]>): Promise<CrossrefMetadata> {
  const endpoint = new URL("https://api.crossref.org/works");
  endpoint.searchParams.set("query.bibliographic", entry.full.slice(0, 700));
  endpoint.searchParams.set("rows", "1");
  // 題と DOI だけでなく、突き合わせに使う分もまとめて貰う。1 件あたり 1 秒かかる
  // 問い合わせなので、あとから足りないと分かっても取りに戻れない。
  endpoint.searchParams.set(
    "select",
    "DOI,title,URL,container-title,short-container-title,volume,page,author,issued,published-print,published-online",
  );

  let response: Response | null = null;
  for (let attempt = 0; attempt <= CROSSREF_RETRIES; attempt += 1) {
    await wait(crossrefNextAt - Date.now());
    crossrefNextAt = Date.now() + crossrefGapMs;
    response = await fetch(endpoint.toString(), { headers: { Accept: "application/json" } });
    crossrefGapMs = crossrefGapFrom(response);
    if (response.status !== 429) break;
    // 混んでいると言われた。相手の言い値、なければ倍々で待つ。
    const retryAfter = Number(response.headers.get("retry-after"));
    const backoff = Number.isFinite(retryAfter) && retryAfter > 0
      ? retryAfter * 1000
      : crossrefGapMs * 2 ** (attempt + 1);
    crossrefNextAt = Date.now() + backoff;
  }
  if (!response || !response.ok) throw new Error(`Crossref: ${response?.status ?? "no response"}`);

  const payload: unknown = await response.json();
  const message = payload !== null && typeof payload === "object"
    ? (payload as Record<string, unknown>).message
    : undefined;
  const items = message !== null && typeof message === "object"
    ? (message as Record<string, unknown>).items
    : undefined;
  const item = Array.isArray(items) ? items[0] : undefined;
  const doi = stringField(item, "DOI");
  const title = firstStringField(item, "title");
  const url = stringField(item, "URL");
  if (!doi && !title && !url) return { state: "not-found" };
  const mismatches = compareWithCrossref(parseEntryFacts(entry.full), crossrefFacts(item));
  return { state: "found", doi, title, url, mismatches };
}

/** Crossref の 1 件から、突き合わせに使う値だけを取り出す。 */
function crossrefFacts(item: unknown): CrossrefFacts {
  const page = stringField(item, "page");
  return {
    journal: firstStringField(item, "container-title"),
    shortJournal: firstStringField(item, "short-container-title"),
    years: crossrefYears(item),
    volume: stringField(item, "volume"),
    // 「1903-1910」 の先頭。原稿が書くのは始まりのページ。
    ...(page ? { firstPage: page.split(/[-–—]/u)[0]!.trim() } : {}),
    ...(crossrefFirstAuthor(item) ? { firstAuthor: crossrefFirstAuthor(item)! } : {}),
  };
}

/**
 * 候補が名乗る出版年、ぜんぶ。
 *
 * `issued`・`published-print`・`published-online` は食い違うことがある（電子版
 * が前年、冊子版が翌年）。**どちらを書いても誤りではない**ので、1 つでも合えば
 * 黙るように全部を返す。
 */
function crossrefYears(item: unknown): readonly number[] {
  const years = new Set<number>();
  for (const key of ["issued", "published-print", "published-online"]) {
    if (item === null || typeof item !== "object") break;
    const value = (item as Record<string, unknown>)[key];
    const parts = value !== null && typeof value === "object"
      ? (value as Record<string, unknown>)["date-parts"]
      : undefined;
    const year = Array.isArray(parts) && Array.isArray(parts[0]) ? Number(parts[0][0]) : NaN;
    if (Number.isInteger(year)) years.add(year);
  }
  return [...years];
}

/** 筆頭著者の姓。`sequence: "first"` があればそれ、無ければ配列の先頭。 */
function crossrefFirstAuthor(item: unknown): string | undefined {
  if (item === null || typeof item !== "object") return undefined;
  const authors = (item as Record<string, unknown>).author;
  if (!Array.isArray(authors) || authors.length === 0) return undefined;
  const first = authors.find((author) => stringField(author, "sequence") === "first") ?? authors[0];
  return stringField(first, "family");
}

function crossrefEnabled(): boolean {
  return prefs.referenceCrossref;
}

/** 一覧を作り直す間隔。1 件ごとに 99 枚のカードを建て直すと、読んでいる側が揺れる。 */
const CROSSREF_REDRAW_MS = 2000;

/**
 * 文献を 1 件ずつ Crossref に問い合わせる。裏で進み、パネルは触れるまま。
 *
 * 速度はサーバーの言うとおり（`lookupCrossref`）。99 件なら 1 分半ほどかかるので、
 * 進み具合は 1 件ごとに出し、一覧そのものの建て直しは間引く。
 */
/**
 * いま走っている問い合わせの世代。
 *
 * 数え直すたびに `enrichReferences` が呼ばれるので、前の回が 99 件の途中でも
 * 新しい回が始まる。世代が変わった時点で古い回は自分から降りる —— 取れた分は
 * 文献の本文で引ける表に残るので、捨てているのは順番待ちだけ。
 */
let crossrefRun = 0;

async function enrichReferences(report: actions.LabelReport): Promise<void> {
  if (!crossrefEnabled()) return;
  const run = (crossrefRun += 1);
  const entries = [...new Map(report.references.flatMap((item) => item.entry ? [[item.entry.full, item.entry]] : [])).values()];
  // 取れなかった分と、途中で降りた分は、次の機会に引き直す。
  for (const entry of entries) {
    const state = crossrefMetadata.get(entry.full)?.state;
    if (state === "failed" || state === "loading") crossrefMetadata.delete(entry.full);
  }
  const pending = entries.filter((entry) => !crossrefMetadata.has(entry.full));
  if (pending.length === 0) return;
  crossrefProgress = { completed: 0, total: pending.length };
  for (const entry of pending) crossrefMetadata.set(entry.full, { state: "loading" });
  renderReferences(report);

  let redrawnAt = Date.now();
  for (const entry of pending) {
    if (crossrefRun !== run) return; // 新しい回が始まっている
    try {
      crossrefMetadata.set(entry.full, await lookupCrossref(entry));
    } catch {
      crossrefMetadata.set(entry.full, { state: "failed" });
    }
    if (crossrefProgress) crossrefProgress = { ...crossrefProgress, completed: crossrefProgress.completed + 1 };
    if (lastLabels !== report) continue;
    updateCrossrefStatus(report);
    if (Date.now() - redrawnAt < CROSSREF_REDRAW_MS) continue;
    redrawnAt = Date.now();
    renderReferences(report);
  }

  if (crossrefRun !== run) return;
  crossrefProgress = null;
  if (lastLabels === report) renderReferences(report);
}

/**
 * Crossref の 1 行だけを書き換える。
 *
 * 終わったときは取れた数だけでなく、**該当なし**と**取得できなかった**数も出す。
 * 出せなかったものを黙って落としていたせいで、速度制限に当たっていることが
 * 「3 件しか出ない」としか見えなかった。
 */
function updateCrossrefStatus(report: actions.LabelReport): void {
  const status = byId("crossref-status");
  if (!crossrefEnabled()) {
    status.hidden = true;
    return;
  }
  status.hidden = false;
  if (crossrefProgress) {
    const { completed, total } = crossrefProgress;
    status.textContent = `Crossref を検索中… ${completed}/${total} 件（Crossref の制限で 1 秒に 1 件ずつ）`;
    return;
  }
  const states = report.references.flatMap((item) =>
    item.entry ? [crossrefMetadata.get(item.entry.full)?.state ?? "loading"] : [],
  );
  const count = (state: string): number => states.filter((value) => value === state).length;
  const notes = [`${count("found")} 件の候補`];
  if (count("not-found") > 0) notes.push(`${count("not-found")} 件は該当なし`);
  if (count("failed") > 0) notes.push(`${count("failed")} 件は取得できず`);
  status.textContent = `Crossref検索が完了しました。${notes.join("、")}。`;
}

function externalLink(url: string, label: string): HTMLAnchorElement {
  const link = document.createElement("a");
  link.href = url;
  link.target = "_blank";
  link.rel = "noopener noreferrer";
  link.textContent = label;
  return link;
}

/** Adds data supplied by Crossref, separately from the document's own entry. */
function crossrefDetails(entry: NonNullable<actions.ReferenceRow["entry"]>): HTMLElement | null {
  if (!crossrefEnabled()) return null;
  const metadata = crossrefMetadata.get(entry.full);
  if (!metadata || metadata.state === "not-found") return null;
  const details = document.createElement("div");
  details.className = "crossref-details";
  if (metadata.state === "loading") {
    details.textContent = "Crossref からタイトル・DOIを検索中…";
    return details;
  }
  if (metadata.state === "failed") {
    // 黙って空けない。取れなかったことと、取り直せることが分かるように。
    details.textContent = "Crossref から取得できませんでした（更新ボタンでやり直せます）。";
    return details;
  }
  const label = document.createElement("span");
  label.className = "crossref-label";
  label.textContent = "Crossref候補";
  details.appendChild(label);
  if (metadata.title) {
    const title = document.createElement("span");
    title.className = "crossref-title";
    title.textContent = metadata.title;
    details.appendChild(title);
  }
  if (metadata.doi) details.append(externalLink(`https://doi.org/${metadata.doi}`, `DOI: ${metadata.doi}`));
  const normalizedDoiUrl = metadata.doi ? `https://doi.org/${metadata.doi}`.toLowerCase() : "";
  if (metadata.url && metadata.url.toLowerCase() !== normalizedDoiUrl) details.append(externalLink(metadata.url, "出版社ページ"));

  // 食い違ったところ。**候補そのものが別の論文であることもある**ので、
  // 「間違い」ではなく「食い違い」として、両方の値を並べて人に決めてもらう。
  const mismatches = metadata.mismatches ?? [];
  if (mismatches.length > 0) {
    const warning = document.createElement("span");
    warning.className = "crossref-mismatch";
    warning.textContent = `候補と違うところ：${mismatches.map(describeMismatch).join("／")}`;
    details.appendChild(warning);
  }
  return details;
}

/** 文献一覧。番号で選び、位置ボタンで本文へ、共通ボタンで文献リストへ移動する。 */
/** 書誌が無い、または本文がどこからも引用していない。図・表の「問題あり」と同じ意味。 */
function hasReferenceIssue(item: actions.ReferenceRow): boolean {
  return item.entry === undefined || item.citations.length === 0;
}

/**
 * Crossref の候補と食い違っている項目。
 *
 * 「問題あり」とは別に数える。あちらは原稿だけを見て言える話（書誌が無い、
 * どこからも引用されていない）で、こちらは**外の情報と突き合わせた結果**。
 * 直すべきなのが原稿か、候補の取り違えかは、人が見ないと決まらない。
 */
function referenceMismatches(item: actions.ReferenceRow): readonly CrossrefMismatch[] {
  if (!crossrefEnabled() || !item.entry) return [];
  return crossrefMetadata.get(item.entry.full)?.mismatches ?? [];
}

/**
 * 「すべて」「問題あり」「未引用」の札。図・表の一覧と同じ作り。
 *
 * 押しても列が変わらない札は出さない —— 全部が問題ありなら 「すべて」 と同じで、
 * 未引用が問題ありの全部なら 「問題あり」 と同じ。効かないボタンに見えるより、
 * 無いほうがいい。返すのは、その結果として有効になった絞り込み。
 */
function renderReferenceChips(report: actions.LabelReport): ReferenceFilter {
  const all = report.references.length;
  const flagged = report.references.filter(hasReferenceIssue).length;
  const uncited = report.references.filter((item) => item.citations.length === 0).length;
  const mismatched = report.references.filter((item) => referenceMismatches(item).length > 0).length;

  show("reference-tools", all > 0);
  const chips = [
    { id: "reference-filter-all", value: "all" as const, label: `すべて ${all}`, hidden: false },
    {
      id: "reference-filter-issue",
      value: "issues" as const,
      label: `問題あり ${flagged}`,
      hidden: flagged === 0 || flagged === all,
    },
    {
      id: "reference-filter-uncited",
      value: "uncited" as const,
      label: `未引用 ${uncited}`,
      hidden: uncited === 0 || uncited === flagged,
    },
    {
      id: "reference-filter-mismatch",
      value: "mismatch" as const,
      label: `要確認 ${mismatched}`,
      hidden: mismatched === 0,
    },
  ];
  if (chips.some((chip) => chip.hidden && chip.value === referenceFilter)) referenceFilter = "all";
  for (const chip of chips) {
    const button = byId(chip.id);
    button.textContent = chip.label;
    button.hidden = chip.hidden;
    button.setAttribute("aria-pressed", String(referenceFilter === chip.value));
  }
  return referenceFilter;
}

function renderReferences(report: actions.LabelReport): void {
  const container = byId("references");
  setSectionCount("count-references", `${report.references.length} 件`);
  const highlightSelect = byId("reference-highlight-select") as HTMLSelectElement;
  const previousHighlight = highlightSelect.value;
  highlightSelect.innerHTML = "";
  for (const item of report.references) {
    const option = document.createElement("option");
    option.value = String(item.number);
    option.textContent = `[${item.number}]（${item.citations.length} 回）`;
    highlightSelect.appendChild(option);
  }
  if ([...highlightSelect.options].some((option) => option.value === previousHighlight)) {
    highlightSelect.value = previousHighlight;
  }
  const query = referenceQuery();
  const authors = prefs.referenceAuthors;
  const selected = report.references.find((item) => item.number === selectedReferenceNumber);
  const target = selected ?? report.references.find((item) => item.number === 1);
  // 行き先が 1 つも無い画面にボタンだけ残っていても、押せることが分からない。
  const jump = byId("reference-list-jump") as HTMLButtonElement;
  const inList = currentView === "references" && report.references.length > 0;
  jump.hidden = !inList;
  byId("reference-settings-wrap").hidden = !inList;
  jump.disabled = target?.entry === undefined;
  // 名前は変えない。行き先だけを添える —— ボタンの絵は本 1 つきりなので、
  // 指している場所が変わったことは、この一行でしか伝わらない。
  jump.title = target?.entry
    ? `本文中の文献リストへ移動（[${target.number}]・${where(target.entry.at.paragraphIndex)}）`
    : "本文中の文献リストへ移動：文献 [1] が文献リストにありません。文献カードを選んでください。";
  const filter = renderReferenceChips(report);
  updateCrossrefStatus(report);
  container.innerHTML = "";

  // 畳んだ行の書誌は、既定では 1 行に切る（全文は開くかホバーで読める）。
  container.classList.toggle("wrap-entries", prefs.referenceWrap === "wrap");

  const items = report.references.filter((item) => {
    const matchesFilter =
      filter === "issues" ? hasReferenceIssue(item)
        : filter === "uncited" ? item.citations.length === 0
          : filter === "mismatch" ? referenceMismatches(item).length > 0
            : true;
    return matchesFilter && matchesQuery(item, query);
  });
  // 何件に当たったかは、探している本人がいちばん知りたい。小窓を開けたまま
  // 打てるので、1 文字ごとに絞られていくのが見える。
  const searching = Object.values(query).some((value) => value.length > 0);
  byId("reference-search-count").textContent = searching
    ? `${report.references.length} 件中 ${items.length} 件が一致`
    : "";
  byId("reference-search-clear").hidden = !searching;
  byId("reference-search-toggle").classList.toggle("active", searching);
  if (items.length === 0) {
    const empty = document.createElement("p");
    empty.className = "lead";
    empty.textContent = report.references.length === 0 ? "引用文献は見つかりませんでした。" : "条件に合う引用文献はありません。";
    container.appendChild(empty);
    return;
  }

  // 開くのは押したものだけ。何も押していなければ、どれも開かない。
  //
  // 以前はここで先頭の 1 枚を開いていた。Crossref の候補が「出ていない」のか
  // 「取れなかった」のかを、1 枚も開いていない一覧では見分けられない、という
  // 理由だったが、**押していないものが開いている**ほうが分からない ——
  // 開いた覚えのない [1] だけが開いていて、閉じ方も無かった。
  // Crossref の進み具合は一覧の上の行（updateCrossrefStatus）が言う。
  const expandAll = prefs.referenceExpand === "all";

  for (const item of items) {
    const missing = item.entry === undefined;
    const uncited = item.citations.length === 0;
    const open = expandAll || openReferences.has(item.number);
    const row = document.createElement("article");
    row.className = `finding reference-item ${missing || uncited ? "severity-fix" : "severity-note"}`;
    row.classList.toggle("selected", item.number === selectedReferenceNumber);
    row.classList.toggle("collapsed", !open);
    row.title = open ? "" : "押すと、この文献の詳しい内容を開きます。";
    row.onclick = (event) => {
      if ((event.target as HTMLElement).closest("button, a, input, select, label")) return;
      selectReference(item.number);
    };

    // 番号・書誌・回数を 1 行に。畳んでいるときはこの行が全部で、開くと
    // 書誌が折り返し、下に Crossref と引用場所が続く。
    const line = document.createElement("div");
    line.className = "reference-line";
    const text = document.createElement("p");
    text.className = "finding-message reference-entry";
    const label = document.createElement("span");
    label.className = "reference-number";
    label.textContent = `[${item.number}]`;
    text.appendChild(label);
    if (item.entry) {
      text.title = item.entry.full;
      appendReferenceText(text, item.entry, authors);
    } else {
      text.append(report.hasBibliography
        ? "文献リストに該当する項目がありません。"
        : "文献リストが見つからないため、書誌は表示できません。");
    }
    // 食い違いの印は、畳んだ行にも出す。開かないと分からない印では、99 件から
    // 見つける役に立たない。中身は開いたときの Crossref の箱に出る。
    const mismatches = referenceMismatches(item);
    const mark = document.createElement("span");
    mark.className = "reference-mismatch-mark";
    mark.textContent = "要確認";
    mark.hidden = mismatches.length === 0;
    if (mismatches.length > 0) {
      mark.title = `Crossref の候補と違うところ：${mismatches.map(describeMismatch).join("／")}`;
      mark.setAttribute("aria-label", mark.title);
    }

    const count = document.createElement("span");
    count.className = "severity";
    count.textContent = uncited ? "引用なし" : `${item.citations.length} 回`;
    line.append(text, mark, count);
    row.appendChild(line);

    // 畳んでいる分は組み立てない。99 件ぶんの Crossref の箱と引用場所を作って
    // から CSS で隠すのでは、行数が減っても重さは減らない。
    if (open) {
      if (item.entry) {
        const details = crossrefDetails(item.entry);
        if (details) row.appendChild(details);
      }
      if (item.citations.length > 0) {
        row.appendChild(placesLine(`文献 [${item.number}]`, item.citations, () => selectReference(item.number)));
      }
    }
    container.appendChild(row);
  }
}

/** Fetches page numbers for the paragraphs a list points at, best effort. */
async function loadPages(paragraphIndices: readonly number[]): Promise<void> {
  pageOf = await actions.paragraphPages([...new Set(paragraphIndices)], options());
}

function positiveNumber(id: string): number {
  const value = Number((byId(id) as HTMLInputElement).value);
  if (!Number.isInteger(value) || value < 1) throw new Error("1 以上の整数を入力してください。");
  return value;
}

function numberInUse(kind: "compounds" | "references", number: number): boolean {
  if (!lastLabels) return false;
  if (kind === "references") return lastLabels.references.some((item) => item.number === number);
  return lastLabels.compounds.some((item) => Number(/^(\d+)/u.exec(item.label)?.[1]) === number);
}

function compoundLabelEdit(): actions.CompoundNumberEdit {
  const from = (byId("compound-from") as HTMLInputElement).value.trim();
  const to = (byId("compound-to") as HTMLInputElement).value.trim();
  if (!/^\d{1,4}[a-z]?$/iu.test(from) || !/^\d{1,4}[a-z]?$/iu.test(to)) {
    throw new Error("化合物番号は 1、1a のように入力してください。");
  }
  return { mode: "replace-label", from: from.toLowerCase(), to: to.toLowerCase() };
}

function compoundLabelInUse(label: string): boolean {
  return lastLabels?.compounds.some((item) => item.label.toLowerCase() === label.toLowerCase()) ?? false;
}

function migrateCompoundNotes(edit: actions.CompoundNumberEdit): void {
  const moved = new Map<string, CompoundNote>();
  for (const [label, note] of compoundNotes) {
    moved.set(actions.editedCompoundNumberText(label, edit), note);
  }
  compoundNotes.clear();
  for (const [label, note] of moved) compoundNotes.set(label, note);
  persistCompoundNotes();
}

function invalidateReview(): void {
  current = null;
  reviewedPages = null;
  show("start-section", true);
  show("result-summary", false);
  show("summary-section", false);
  show("findings-section", false);
  show("fixed-section", false);
  show("ignored-section", false);
}

async function editNumbers(
  kind: "compounds" | "references",
  edit: actions.NumberEdit | actions.CompoundNumberEdit,
): Promise<void> {
  if (kind === "compounds" && edit.mode === "replace-label") {
    if (edit.from === edit.to) {
      setStatus("変更前と変更後が同じ番号です。");
      return;
    }
    if (!compoundLabelInUse(edit.from)) {
      setStatus(`化合物 ${edit.from} は一覧にありません。`);
      return;
    }
    if (compoundLabelInUse(edit.to)) {
      setStatus(`化合物 ${edit.to} はすでに使われています。`);
      return;
    }
  } else if (edit.mode === "replace") {
    if (edit.from === edit.to) {
      setStatus("変更前と変更後が同じ番号です。");
      return;
    }
    if (!numberInUse(kind, edit.from)) {
      setStatus(`番号 ${edit.from} は一覧にありません。`);
      return;
    }
    if (numberInUse(kind, edit.to)) {
      setStatus(`番号 ${edit.to} はすでに使われています。`);
      return;
    }
  }

  const name = kind === "compounds" ? "化合物番号" : "文献番号";
  setStatus(`${name}を本文全体で変更しています…`, true);
  const changed =
    kind === "compounds"
      ? await actions.editCompoundNumbers(edit, options())
      : await actions.editReferenceNumbers(edit as actions.NumberEdit, options());
  if (changed === 0) {
    setStatus("変更対象が見つかりませんでした。一覧を作り直してください。");
    return;
  }
  if (kind === "compounds") migrateCompoundNotes(edit);
  invalidateReview();
  if (kind === "compounds") await listCompounds();
  else await listReferences();
  setStatus(`${name}を ${changed} 箇所変更しました。取り消しは ⌘Z（Ctrl+Z）です。`);
}

