/**
 * 一覧の上の 1 行に続ける、言い切りの文.
 *
 * 「99 件の文献番号。本文が引用していない番号：56。」 と書いていた。名詞を並べた
 * 覚え書きで、**何が起きているのかを言っていない** —— 56 が引用されていないのか、
 * 56 件が引用されていないのか、読んだだけでは決まらない。一つ一つを文にする。
 */
function referenceNotes(report: actions.LabelReport): string[] {
  const notes: string[] = [];
  if (!report.hasBibliography) {
    // 「見つかりませんでした」だけでは打つ手がない。どこで読めなくなったかまで出す。
    notes.push(report.bibliographyNote ?? "末尾の文献リストは見つかりませんでした。");
  }
  if (report.missingEntries.length > 0) {
    notes.push(`文献番号 ${numberList(report.missingEntries)} は文献リストにありません。`);
  }
  if (report.uncited.length > 0) {
    notes.push(`文献番号 ${numberList(report.uncited)} は本文で引用されていません。`);
  }
  if (notes.length === 0) notes.push("本文と文献リストの対応に漏れはありません。");
  return notes;
}

/** 番号をいくつまで並べるか。これを超えると読むより数えるほうが早くなる。 */
const NUMBER_LIST_LIMIT = 12;

/** 「3、4、5」「Figure 4、Figure 5」。多すぎるときは打ち切って、残りの数を言う。 */
function numberList(numbers: readonly (number | string)[]): string {
  const head = numbers.slice(0, NUMBER_LIST_LIMIT).join("、");
  const rest = numbers.length - NUMBER_LIST_LIMIT;
  return rest > 0 ? `${head} ほか ${rest} 件` : head;
}

/** Lists every Figure/Fig./Table/図/表 label with its caption and text references. */
