/** Records painted spans so the clear command knows what is the add-in's to undo. */
function remember(findings: readonly Finding[]): void {
  const seen = new Set(painted.map(ignoreKey));
  painted = [...painted, ...findings.filter((f) => !seen.has(ignoreKey(f)))];
}

async function clearHighlights(): Promise<void> {
  setStatus("このアドインが塗った箇所を消去中…", true);
  // With no record of what was painted — a pane reopened since — fall back to
  // the current review's spans and to every space, which is the widest set this
  // add-in could have painted.
  const blind = painted.length === 0;
  const findingCount = await actions.clearHighlights(options(), {
    findings: blind ? selected() : painted,
    spaces: paintedSpaces || blind,
  });
  const fontCount = await actions.clearFontHighlightsEverywhere(paintedFonts, options());
  const styleCount = await actions.clearCharacterStyleHighlightsEverywhere(paintedCharacterStyles, options());
  const compoundCount = await actions.clearCompoundLabelHighlightsEverywhere(paintedCompoundLabels, options());
  const referenceMarkerCount = await actions.clearReferenceNumberHighlightsEverywhere(paintedReferenceMarkers, false, options());
  const referenceNumberCount = await actions.clearReferenceNumberHighlightsEverywhere(paintedReferenceNumbers, true, options());
  const n = findingCount + fontCount + styleCount + compoundCount + referenceMarkerCount + referenceNumberCount;
  painted = [];
  paintedSpaces = false;
  paintedFonts.clear();
  paintedCharacterStyles.clear();
  paintedCompoundLabels.clear();
  paintedReferenceMarkers.clear();
  paintedReferenceNumbers.clear();
  setStatus(
    n === 0
      ? "消せるハイライトが見つかりませんでした。手で塗ったマーカーごと消すには、リボンの［ハイライトを全て削除］を使ってください。"
      : `${n} 箇所のハイライトを消去しました（手で塗ったマーカーは残しています）。`,
  );
}
