/* global Office */
/**
 * 原稿ファイルそのものに残す値.
 *
 * Two kinds of memory sit side by side in this add-in and they are not
 * interchangeable. `prefs.ts` keeps what belongs to the *person* — which rules
 * run, what the marker colors are — in `localStorage`, on this machine, for
 * every document. This keeps what belongs to the *document* in the document,
 * through Office's own per-document settings, so it survives closing Word and
 * follows the file if it is copied or mailed.
 *
 * The distinction is the reason 「無視」 lives here and nowhere else: an ignored
 * finding is a judgement about one draft, and would be wrong applied to the next
 * one.
 *
 * Office writes these into the file, but only when the *document* is saved —
 * `saveAsync` marks it as changed and nothing more. A user who closes without
 * saving loses the ignores along with everything else they did, which is the
 * behaviour they already expect from Word.
 *
 * Every path here is best-effort. The mock harness has no `Office.context`, an
 * older host may not offer document settings at all, and neither is worth
 * refusing to open the pane over.
 */

function settings(): Office.Settings | null {
  try {
    return Office.context?.document?.settings ?? null;
  } catch {
    return null; // No host, or a host without per-document settings.
  }
}

/** Whatever was stored under `key`, or null. Callers must validate the shape. */
export function readDocumentValue(key: string): unknown {
  try {
    return settings()?.get(key) ?? null;
  } catch {
    return null;
  }
}

/**
 * Stores `value` under `key`, to be written into the file when it is saved.
 *
 * Fire-and-forget: the result of `saveAsync` is nothing the user could act on,
 * and a read-only document — where it fails — is one they cannot save anyway.
 */
export function writeDocumentValue(key: string, value: unknown): void {
  const store = settings();
  if (!store) return;
  try {
    store.set(key, value);
    store.saveAsync(() => undefined);
  } catch {
    // Read-only, or a host that declines. The list still works for this session.
  }
}
