/* global Word */
/**
 * Turning a `(paragraphIndex, start, matched)` triple into a `Word.Range`.
 *
 * The Word JS API has no "range at character offset N" call, so the offset is
 * resolved the only way available: search the paragraph for the matched text and
 * take the Nth hit, where N is how many identical strings precede it. That is
 * exact as long as the search sees the same substrings the rules did, which is
 * why matching is forced to be case- and width-sensitive.
 */
import type { Finding } from "../core/types.ts";

/**
 * The three fields it takes to find something again.
 *
 * A `Finding` has them, and so does an inventory occurrence — 化合物番号 and
 * 文献番号 are not mistakes, but jumping to them is the same problem.
 */
export interface Locatable {
  readonly paragraphIndex: number;
  readonly start: number;
  readonly matched: string;
}

/** Word's search box rejects strings longer than this. */
const MAX_SEARCH_LENGTH = 255;

/**
 * `^` introduces Word's special codes (^p, ^t) even with wildcards off, so a
 * literal caret has to be doubled.
 */
export function escapeSearch(term: string): string {
  return term.replace(/\^/gu, "^^");
}

/** The search term for a finding, shortened when the matched span is huge. */
export function searchTermFor(matched: string): string {
  return escapeSearch(matched.slice(0, MAX_SEARCH_LENGTH));
}

/**
 * Which hit of `matched` within the paragraph begins at `start`, or -1 when the
 * text at that offset is not `matched` at all.
 *
 * Counting steps over each hit in full, because Word's search returns
 * non-overlapping results: in "aaa", searching "aa" yields one range, not two.
 */
export function occurrenceIndex(paragraphText: string, matched: string, start: number): number {
  if (matched.length === 0) return -1;
  let n = 0;
  let from = 0;
  for (;;) {
    const at = paragraphText.indexOf(matched, from);
    if (at === -1 || at > start) return -1;
    if (at === start) return n;
    n += 1;
    from = at + matched.length;
  }
}

/** Search options that make Word agree with the rules about what "equal" means. */
export const EXACT: Word.SearchOptions | object = {
  matchCase: true,
  matchWholeWord: false,
  matchWildcards: false,
  ignorePunct: false,
  ignoreSpace: false,
};

export interface Located<T extends Locatable = Finding> {
  readonly finding: T;
  readonly range: Word.Range;
}

/**
 * Resolves findings to ranges, one `context.sync()` for the whole batch.
 *
 * Findings whose text no longer matches the document (because an earlier fix
 * moved it) are dropped rather than applied to the wrong place.
 */
export async function locateFindings<T extends Locatable>(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  paragraphTexts: readonly string[],
  findings: readonly T[],
): Promise<Array<Located<T>>> {
  interface Pending {
    readonly finding: T;
    readonly ordinal: number;
    readonly results: Word.RangeCollection;
  }

  const pending: Pending[] = [];
  for (const item of findings) {
    const paragraph = paragraphs[item.paragraphIndex];
    const text = paragraphTexts[item.paragraphIndex];
    if (!paragraph || text === undefined) continue;

    const term = searchTermFor(item.matched);
    if (term.trim().length === 0 && item.matched.trim().length === 0) continue;
    if (term.length === 0) continue;

    const ordinal = occurrenceIndex(text, item.matched.slice(0, MAX_SEARCH_LENGTH), item.start);
    if (ordinal < 0) continue;

    const results = paragraph.search(term, EXACT);
    results.load("items");
    pending.push({ finding: item, ordinal, results });
  }

  await context.sync();

  const located: Array<Located<T>> = [];
  for (const { finding, ordinal, results } of pending) {
    const range = results.items[ordinal];
    if (!range) continue;
    located.push({ finding, range });
  }
  return located;
}
