/**
 * 2. 書式上の誤り — 黄マーカー（フォント関係を除くテキスト判定分）.
 *
 * Dashes, primes, reagent shorthand, and half-width spaces. The font-dependent
 * items (日英フォントの不一致, ギリシャ文字のフォント, 太字, イタリック) cannot be
 * decided from text alone and live in `src/office/formatChecks.ts`.
 */
import { ALKYL_GROUPS, ALKYL_PREFIXES, EN_DASH_PAIRS, UNITS } from "../dict.ts";
import type { DocumentRule, Finding, ParagraphRule } from "../types.ts";
import { finding } from "../types.ts";
import { escapeRegExp, matchAll } from "../text.ts";
import { isOrbital } from "../labels.ts";

/**
 * 範囲を示す横棒は en dash（ハイフンではない）.
 *
 * The hard part is telling a range (25-30 °C) from a locant in a compound name
 * (1,3-butadiene, 2-butanol). A locant is followed by a letter and is usually
 * preceded by a comma or the start of a name, so both of those shapes are
 * excluded rather than guessed at.
 *
 * Basis sets are the other shape that must survive untouched: in 6-31G(d) or
 * 6-311++G(d,p) the hyphen is part of the name, and Pople's convention keeps it
 * a hyphen. Letting the trailing lookahead skip over `+`/`*`/`-` catches the G,
 * and refusing a digit there stops the number from backtracking — without it
 * 「6-31G」 gives up its G and reports 「6-3」 instead.
 */
const NUMERIC_RANGE = /(?<![,\d–-])(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)(?![-–+*]*[A-Za-z(0-9])/gu;

export const rangeDashRule: ParagraphRule = {
  id: "range-dash",
  category: "format",
  title: "範囲の横棒は en dash",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const m of matchAll(NUMERIC_RANGE, text)) {
      const replacement = `${m[1]}–${m[2]}`;
      if (m[0] === replacement) continue;
      found.push(
        finding(rangeDashRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: m.index,
          matched: m[0],
          replacement,
          message: `範囲を示す横棒はハイフンでなく en dash（–）：「${m[0]}」→「${replacement}」`,
        }),
      );
    }
    return found;
  },
};

/**
 * 化合物命名に使う横棒はハイフン（en dash ではない）— the mirror image of the rule
 * above. An en dash between a locant/prefix and a name is a typographic slip,
 * usually from an autocorrect that turned "2-butanol" into "2–butanol".
 *
 * The hard part is that an en dash between two words is usually *correct*:
 * HOMO–LUMO, compounds a–f, π–π stacking. So both sides have to look like a
 * chemical name, not merely like text.
 *
 * Left — a locant (2, 1,3) or a naming prefix **standing on its own**. That word
 * boundary is what keeps the O of HOMO–LUMO out: it is preceded by a letter.
 * Right — a lower-case name fragment (butanol) or a known group (BuLi). That is
 * what keeps 「compounds a–f」 and 「π–π」 out.
 *
 * Single letters that double as compound labels (a, b, c …) are deliberately
 * absent from the prefix list; 「1a–1f」 and 「a–f」 are ranges, not names.
 */
const NAME_PREFIXES: readonly string[] = [
  "tert", "trans", "cyclo", "sec", "neo", "iso", "cis",
  "n", "i", "s", "t", "o", "m", "p",
  "N", "O", "S", "P", "E", "Z", "R", "D", "L",
  "α", "β", "γ", "δ", "π", "σ", "ω",
];

/** Right-hand fragments that are names despite starting with a capital. */
const NAME_GROUPS: readonly string[] = [
  ...ALKYL_GROUPS, "Me", "Et", "Ph", "Bn", "Ac", "Ts", "Tf", "Ms", "Boc", "Cbz",
];

const byLengthDesc = (a: string, b: string): number => b.length - a.length;

const COMPOUND_EN_DASH = new RegExp(
  "(?<![A-Za-z0-9])" +
    `(\\d+(?:,\\d+)*|${[...NAME_PREFIXES].sort(byLengthDesc).map(escapeRegExp).join("|")})` +
    "–" +
    `([a-z]{3,}|(?:${[...NAME_GROUPS].sort(byLengthDesc).join("|")})(?![a-z]))`,
  "gu",
);

export const compoundHyphenRule: ParagraphRule = {
  id: "compound-hyphen",
  category: "format",
  title: "化合物名の横棒はハイフン",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const m of matchAll(COMPOUND_EN_DASH, text)) {
      const replacement = `${m[1]}-${m[2]}`;
      found.push(
        finding(compoundHyphenRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: m.index,
          matched: m[0],
          replacement,
          message: `化合物命名の横棒は en dash でなくハイフン（-）：「${m[0]}」→「${replacement}」`,
        }),
      );
    }
    return found;
  },
};

/**
 * 化合物名や番号などに付けるプライムがアポストロフィーになっているので修正する.
 *
 * An apostrophe after a digit, a closing bracket, or a capital letter is a
 * prime. English contractions (don't, 5's) are excluded by requiring that the
 * character after the mark is not a lowercase letter.
 */
const PRIME_AS_APOSTROPHE = /([0-9A-Za-z\])])(['’‘`´])(?![a-z])/gu;

export const primeRule: ParagraphRule = {
  id: "prime-apostrophe",
  category: "format",
  title: "プライムがアポストロフィーになっている",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const m of matchAll(PRIME_AS_APOSTROPHE, text)) {
      const replacement = `${m[1]}′`;
      found.push(
        finding(primeRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: m.index,
          matched: m[0],
          replacement,
          message: `プライムはアポストロフィー（${m[2]}）でなく U+2032（′）：「${m[0]}」→「${replacement}」`,
        }),
      );
    }
    return found;
  },
};

/**
 * 半角スペースの使い方の誤り① 必要なところに入っていないので追加が必要.
 *
 * Two shapes are unambiguous enough to act on: a number glued to its unit
 * (10mL) and an operator with no breathing room (x=5). `%`, `°`, and `′` are
 * excluded because they conventionally close up against the number.
 */
const UNIT_ALT = [...UNITS].sort((a, b) => b.length - a.length).map(escapeRegExp).join("|");

const UNIT_PATTERN = new RegExp(
  `(?<![A-Za-z0-9.])(\\d+(?:\\.\\d+)?)(${UNIT_ALT})(?![A-Za-z0-9])`,
  "gu",
);

const TIGHT_OPERATOR = /(?<=[A-Za-z0-9Ͱ-Ͽ)])([=<>≤≥±×])(?=[-−–]?[A-Za-z0-9.(Ͱ-Ͽ])/gu;
const NUMBER_AHEAD = /^[-−–]?\d/u;

/**
 * 「18d」 is a compound number far more often than it is 18 days, and the two want
 * opposite things — a label closes up, a value takes a space. `compoundLabels`
 * has already read the whole document for the two signals that settle it
 * (「化合物 18d」, or a series such as 18a/18d); this only asks about the shape.
 */
const AMBIGUOUS_LABEL = /^\d+[a-z]$/u;

export const missingSpaceRule: ParagraphRule = {
  id: "space-missing",
  category: "format",
  title: "半角スペースの誤り①（不足）",
  kind: "paragraph",
  run(text, index, ctx): Finding[] {
    const found: Finding[] = [];

    for (const m of matchAll(UNIT_PATTERN, text)) {
      const replacement = `${m[1]} ${m[2]}`;
      const ambiguous = AMBIGUOUS_LABEL.test(m[0]);
      // Settled: the document numbers compounds this way. Nothing to say.
      if (ambiguous && ctx.compoundLabels.has(m[0])) continue;
      // 「2s 軌道」「3d 電子」 — s は秒、d は日でもあるので、この形は単位付きの数値
      // にも見える。軌道は化合物でも数値でもないので、どちらの側からも黙る。
      if (ambiguous && isOrbital(text, m.index, m[0])) continue;
      found.push(
        finding(missingSpaceRule, {
          severity: ambiguous ? "confirm" : "fix",
          paragraphIndex: index,
          start: m.index,
          matched: m[0],
          replacement,
          message: ambiguous
            ? `数値と単位なら半角スペース：「${m[0]}」→「${replacement}」（化合物番号なら、このままで正しい）`
            : `数値と単位の間に半角スペース：「${m[0]}」→「${replacement}」`,
        }),
      );
    }

    for (const m of matchAll(TIGHT_OPERATOR, text)) {
      const before = text[m.index - 1] ?? "";
      const after = text[m.index + 1] ?? "";
      // 「C=C」「C=O」 is a double bond, not an equation. The checklist's item is
      // 「記号 = 数値」, so an `=` only counts as an operator when a number
      // follows it — everything else is chemistry and stays closed up.
      if (m[1] === "=" && !NUMBER_AHEAD.test(text.slice(m.index + 1))) continue;
      const matched = `${before}${m[1]}${after}`;
      found.push(
        finding(missingSpaceRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: m.index - 1,
          matched,
          replacement: `${before} ${m[1]} ${after}`,
          message: `演算子の前後に半角スペース：「${matched}」→「${before} ${m[1]} ${after}」`,
        }),
      );
    }

    return found;
  },
};

/**
 * 負の値の前に付く横棒は en dash（–）.
 *
 * 「-78 °C」 is typed with the keyboard's hyphen, which is a shorter, thinner mark
 * than the one the value wants. The rule is deliberately anchored to a unit: a
 * hyphen before a bare number is far more often a locant (2-butanol), a page
 * range, or a basis set, and 「範囲の横棒」 already owns the range case.
 *
 * The lookbehind is what separates a sign from a range — in 「25-30 °C」 the mark
 * sits between two digits, and that is a range, not a minus.
 */
const NEGATIVE_VALUE = new RegExp(
  `(?<![A-Za-z0-9)\\]–-])([-−])(\\d+(?:\\.\\d+)?)(?=\\s*(?:${UNIT_ALT})(?![A-Za-z0-9]))`,
  "gu",
);

export const negativeDashRule: ParagraphRule = {
  id: "negative-dash",
  category: "format",
  title: "負号は en dash",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const m of matchAll(NEGATIVE_VALUE, text)) {
      const replacement = `–${m[2]}`;
      const name = m[1] === "-" ? "ハイフン" : "マイナス記号（U+2212）";
      found.push(
        finding(negativeDashRule, {
          severity: "fix",
          paragraphIndex: index,
          start: m.index,
          matched: m[0],
          replacement,
          message: `負号は${name}でなく en dash（–）：「${m[0]}」→「${replacement}」`,
        }),
      );
    }
    return found;
  },
};

/**
 * ℃ は 「°」＋「C」 の 2 文字で書く.
 *
 * ℃ (U+2103), ℉ (U+2109) and º (U+00BA, the ordinal indicator that sits next to
 * ° on some keyboards) are single characters that *look* right and behave wrong:
 * they carry their own font metrics, they do not always survive conversion to
 * PDF or to a journal's typesetting, and the SI spells the unit as two
 * characters. On a Mac the degree sign is ⌥（option）+ shift + 8.
 */
const UNIT_CHARACTERS: ReadonlyArray<{ re: RegExp; to: string; why: string }> = [
  { re: /℃/gu, to: "°C", why: "℃（1 文字）ではなく「°」＋「C」の 2 文字" },
  { re: /℉/gu, to: "°F", why: "℉（1 文字）ではなく「°」＋「F」の 2 文字" },
  { re: /º(?=\s*[CF])/gu, to: "°", why: "序数記号 º ではなく度記号 °（U+00B0）" },
];

export const celsiusSignRule: ParagraphRule = {
  id: "celsius-sign",
  category: "format",
  title: "℃ は °C と書く",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const { re, to, why } of UNIT_CHARACTERS) {
      for (const m of matchAll(re, text)) {
        found.push(
          finding(celsiusSignRule, {
            severity: "fix",
            paragraphIndex: index,
            start: m.index,
            matched: m[0],
            replacement: to,
            message: `${why}：「${m[0]}」→「${to}」（Mac では ⌥ + shift + 8 で °）`,
          }),
        );
      }
    }
    return found;
  },
};

/** 半角スペースの使い方の誤り② 必要ないところに入っているので削除が必要. */
export const extraSpaceRule: ParagraphRule = {
  id: "space-extra",
  category: "format",
  title: "半角スペースの誤り②（余分）",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];

    const cases: Array<{ re: RegExp; fix: (m: RegExpExecArray) => string; why: string }> = [
      // 和文の前後に付いた半角スペース（全角文字どうしの間）
      {
        re: /([぀-ヿ一-鿿])[ 　]+([぀-ヿ一-鿿])/gu,
        fix: (m) => `${m[1]}${m[2]}`,
        why: "和文どうしの間の空白は不要",
      },
      // 句読点・閉じ括弧の直前の空白
      {
        re: /[ ]+([,.;:)\]、。，．）」』])/gu,
        fix: (m) => m[1]!,
        why: "句読点・閉じ括弧の直前の空白は不要",
      },
      // 開き括弧の直後の空白
      {
        re: /([(\[（「『])[ ]+/gu,
        fix: (m) => m[1]!,
        why: "開き括弧の直後の空白は不要",
      },
      // 連続した空白
      {
        re: /[ ]{2,}/gu,
        fix: () => " ",
        why: "空白が連続しています",
      },
      // 全角スペース（和文組版の字下げ以外では使わない）
      {
        re: /(?<=\S)　+/gu,
        fix: () => " ",
        why: "全角スペースが使われています",
      },
    ];

    for (const { re, fix, why } of cases) {
      for (const m of matchAll(re, text)) {
        const replacement = fix(m);
        if (replacement === m[0]) continue;
        found.push(
          finding(extraSpaceRule, {
            severity: "fix",
            paragraphIndex: index,
            start: m.index,
            matched: m[0],
            replacement,
            message: `${why}：「${m[0].replace(/ /gu, "␣").replace(/　/gu, "□")}」→「${replacement.replace(/ /gu, "␣")}」`,
          }),
        );
      }
    }

    return found;
  },
};

/**
 * n-BuLi or nBuLi など，様式の統一.
 *
 * Both spellings are defensible; using both in one manuscript is not. The
 * document is scanned for every reagent shorthand, grouped by prefix+group, and
 * a group is reported only when it appears in more than one surface form.
 */
const ALKYL_PATTERN = new RegExp(
  `\\b(${[...ALKYL_PREFIXES].sort((a, b) => b.length - a.length).join("|")})(-?)(${[...ALKYL_GROUPS]
    .sort((a, b) => b.length - a.length)
    .join("|")})\\b`,
  "gu",
);

export const reagentStyleRule: DocumentRule = {
  id: "reagent-style",
  category: "format",
  title: "n-BuLi / nBuLi の様式統一",
  kind: "document",
  run(paragraphs): Finding[] {
    interface Hit {
      readonly paragraphIndex: number;
      readonly start: number;
      readonly text: string;
      readonly key: string;
      readonly hyphenated: boolean;
    }

    const hits: Hit[] = [];
    paragraphs.forEach((p, paragraphIndex) => {
      for (const m of matchAll(ALKYL_PATTERN, p)) {
        hits.push({
          paragraphIndex,
          start: m.index,
          text: m[0],
          key: `${m[1]}${m[3]}`,
          hyphenated: m[2] === "-",
        });
      }
    });

    const styles = new Map<string, Set<boolean>>();
    for (const hit of hits) {
      if (!styles.has(hit.key)) styles.set(hit.key, new Set());
      styles.get(hit.key)!.add(hit.hyphenated);
    }

    // House style = whichever form the manuscript uses more often overall.
    const hyphenated = hits.filter((h) => h.hyphenated).length;
    const preferHyphen = hyphenated >= hits.length - hyphenated;

    const found: Finding[] = [];
    for (const hit of hits) {
      if (styles.get(hit.key)!.size < 2) continue;
      if (hit.hyphenated === preferHyphen) continue;
      const [, prefix, , group] = ALKYL_PATTERN.exec(hit.text) ?? [];
      ALKYL_PATTERN.lastIndex = 0;
      if (!prefix || !group) continue;
      const replacement = preferHyphen ? `${prefix}-${group}` : `${prefix}${group}`;
      found.push(
        finding(reagentStyleRule, {
          severity: "confirm",
          paragraphIndex: hit.paragraphIndex,
          start: hit.start,
          matched: hit.text,
          replacement,
          message: `試薬表記の様式が混在しています：「${hit.text}」→「${replacement}」に統一`,
        }),
      );
    }
    return found;
  },
};

/**
 * ギリシャ文字と和文の間の半角スペース（π共役 → π 共役）.
 *
 * Journals disagree about whether this space is required, so the rule is
 * `confirm` and ships switched off; a lab that wants it turns it on once in
 * 「ルール設定」. Only Greek/和文 boundaries are considered — Latin letters next to
 * 和文 are far too common to flag.
 */
const GREEK = "\\u0370-\\u03FF\\u1F00-\\u1FFF";
const CJK = "\\u3040-\\u30FF\\u3400-\\u4DBF\\u4E00-\\u9FFF";
const GREEK_CJK_BOUNDARY = new RegExp(`([${GREEK}][${CJK}])|([${CJK}][${GREEK}])`, "gu");

/**
 * The same boundary once 「ギリシャ文字は Symbol フォント」 has been applied.
 *
 * That fix rewrites π as a Symbol-font 「p」, and from that moment the character
 * is an ordinary Latin letter as far as any text rule can tell — the pattern
 * above stops matching, and 「和文と英数字の間隔」 deliberately abstains from lone
 * letters for exactly this reason. So 「π共役」 became 「p共役」 and nothing asked
 * for the space any more.
 *
 * Whether that 「p」 is a π is a font question, and only `src/office` can ask it.
 * This pattern over-reports on purpose: every lone letter beside 和文 is offered,
 * and `dropNonSymbolLetters` takes back the ones that are not in Symbol. A host
 * that cannot read fonts keeps them all, which is the safer direction for a
 * rule that only ever suggests a space.
 */
const SYMBOL_CJK_BOUNDARY = new RegExp(
  `((?<![A-Za-z0-9])[A-Za-z][${CJK}])|([${CJK}][A-Za-z](?![A-Za-z0-9]))`,
  "gu",
);

export const greekSpacingRule: ParagraphRule = {
  id: "greek-cjk-space",
  category: "format",
  title: "ギリシャ文字と和文の間隔",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const m of matchAll(GREEK_CJK_BOUNDARY, text)) {
      const pair = m[0];
      const replacement = `${pair[0]} ${pair[1]}`;
      found.push(
        finding(greekSpacingRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: m.index,
          matched: pair,
          replacement,
          message: `ギリシャ文字と和文の間に半角スペース：「${pair}」→「${replacement}」（投稿規程を確認）`,
        }),
      );
    }

    for (const m of matchAll(SYMBOL_CJK_BOUNDARY, text)) {
      const pair = m[0];
      const replacement = `${pair[0]} ${pair[1]}`;
      found.push(
        finding(greekSpacingRule, {
          severity: "confirm",
          paragraphIndex: index,
          start: m.index,
          matched: pair,
          replacement,
          message: `ギリシャ文字と和文の間に半角スペース：「${pair}」→「${replacement}」（投稿規程を確認）`,
        }),
      );
    }

    return found.sort((a, b) => a.start - b.start);
  },
};

/**
 * 和文と欧文（英数字）の間には半角スペースを入れる（Figure 1に示す → Figure 1 に示す）.
 *
 * `\p{sc=...}` is deliberate rather than a hand-written range: it keeps 、。「」
 * and ・ー out, which are punctuation and want no space beside them. Greek is
 * excluded too — that boundary is 「ギリシャ文字と和文の間隔」's job, and it is a
 * convention journals disagree about.
 *
 * A run of a single *letter* is skipped, which matters more than it looks.
 * 「ギリシャ文字は Symbol フォント」 rewrites α as a Symbol-font "a", and from then on
 * this rule cannot tell that letter apart from an English one — it would start
 * demanding 「に a 線」 for text that reads 「にα線」. One letter beside 和文 is a
 * symbol (Greek, a variable, a compound label), and its spacing is that other
 * rule's question. A lone *digit* is not ambiguous that way, so 「Figure 1に」 and
 * 「3種類」 are still reported.
 */
const JA_CHAR = /[\p{sc=Hiragana}\p{sc=Katakana}\p{sc=Han}]/u;
const LATIN_RUN = /[A-Za-z0-9]+/gu;
const LONE_LETTER = /^[A-Za-z]$/u;

export const japaneseLatinSpacingRule: ParagraphRule = {
  id: "ja-latin-space",
  category: "format",
  title: "和文と英数字の間隔",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];

    const report = (start: number, stop: number): void => {
      const matched = text.slice(start, stop);
      // Every gap inside such a span wants a space, so spacing out the whole
      // thing is the replacement, whether it is 2 characters or 3.
      const replacement = [...matched].join(" ");
      found.push(
        finding(japaneseLatinSpacingRule, {
          severity: "fix",
          paragraphIndex: index,
          start,
          matched,
          replacement,
          message: `和文と英数字の間に半角スペース：「${matched}」→「${replacement}」`,
        }),
      );
    };

    for (const m of matchAll(LATIN_RUN, text)) {
      if (LONE_LETTER.test(m[0])) continue;
      const end = m.index + m[0].length;
      const before = JA_CHAR.test(text[m.index - 1] ?? "");
      const after = JA_CHAR.test(text[end] ?? "");


      // 「その3種類」: reporting both boundaries of a one-character run would
      // produce two overlapping findings, and only one of them could be applied.
      if (before && after && m[0].length === 1) {
        report(m.index - 1, end + 1);
        continue;
      }
      if (before) report(m.index - 1, m.index + 1);
      if (after) report(end - 1, end + 1);
    }

    return found;
  },
};

const DIGIT = /[0-9]/u;

/**
 * The run of digits a 「和文と英数字の間隔」 finding touches, or null when its
 * Latin side is letters.
 *
 * Superscript digits after 和文 are citation numbers（である^14，）, and those want
 * no space. Whether they are superscript is a Word question, so the rule reports
 * them and `dropSuperscriptCitations` takes them back out — this is the pure
 * half, which says *which characters* the Office layer should go and look at.
 */
export function digitRunFor(
  text: string,
  finding: { start: number; end: number },
): { readonly start: number; readonly end: number; readonly text: string } | null {
  let at = -1;
  for (let i = finding.start; i < finding.end; i += 1) {
    if (DIGIT.test(text[i] ?? "")) {
      at = i;
      break;
    }
  }
  if (at < 0) return null;

  let start = at;
  let end = at + 1;
  while (start > 0 && DIGIT.test(text[start - 1]!)) start -= 1;
  while (end < text.length && DIGIT.test(text[end]!)) end += 1;
  return { start, end, text: text.slice(start, end) };
}

/**
 * 対等な 2 つを結ぶ横棒は en dash（HOMO-LUMO → HOMO–LUMO）.
 *
 * 「範囲の横棒」 handles 25-30, where both sides are numbers and the shape alone
 * settles it. This one cannot work that way: 「HOMO-LUMO」, 「n-BuLi」 and
 * 「well-known」 are indistinguishable as text, so the rule only fires on pairs
 * named in `EN_DASH_PAIRS`. Missing a pair is a silent no-op; guessing would
 * rewrite every hyphenated compound name in the manuscript.
 *
 * Matching is case-insensitive so 「donor-acceptor」 and 「Donor-Acceptor」 both
 * fire, and the replacement keeps whatever case was written.
 */
const EN_DASH_PAIR = new RegExp(
  `(?<![A-Za-z0-9-])(${EN_DASH_PAIRS.map(([a]) => escapeRegExp(a)).join("|")})-(${EN_DASH_PAIRS.map(
    ([, b]) => escapeRegExp(b),
  ).join("|")})(?![A-Za-z0-9-])`,
  "giu",
);

/** Pairs as written, lower-cased, so a match can be checked against the list. */
const PAIR_KEYS = new Set(EN_DASH_PAIRS.map(([a, b]) => `${a}-${b}`.toLowerCase()));

export const pairDashRule: ParagraphRule = {
  id: "pair-dash",
  category: "format",
  title: "対になる語を結ぶ横棒は en dash",
  kind: "paragraph",
  run(text, index): Finding[] {
    const found: Finding[] = [];
    for (const m of matchAll(EN_DASH_PAIR, text)) {
      // 二つの選択肢を別々に並べているので、HOMO-Alder のような組み合わせも
      // 形の上では通る。実在する組だけを残す。
      if (!PAIR_KEYS.has(`${m[1]}-${m[2]}`.toLowerCase())) continue;
      const replacement = `${m[1]}–${m[2]}`;
      found.push(
        finding(pairDashRule, {
          severity: "fix",
          paragraphIndex: index,
          start: m.index,
          matched: m[0],
          replacement,
          message: `対になる語を結ぶ横棒は en dash（–）：「${m[0]}」→「${replacement}」`,
        }),
      );
    }
    return found;
  },
};

export const FORMAT_RULES = [
  rangeDashRule,
  pairDashRule,
  negativeDashRule,
  celsiusSignRule,
  compoundHyphenRule,
  primeRule,
  missingSpaceRule,
  extraSpaceRule,
  japaneseLatinSpacingRule,
  greekSpacingRule,
  reagentStyleRule,
];
