/**
 * The 「無視」 list.
 *
 * Ignoring belongs to *this* draft, so the list is stored in the draft: the
 * findings go into the document's own add-in settings and come back when the
 * document is next opened. Keeping it in memory instead meant a manuscript
 * corrected over several days made the user re-dismiss the same findings every
 * morning, which is the whole reason anybody presses 「無視」 in the first place.
 *
 * The cost is that the list travels with the file. Hand the draft to a co-author
 * and their pane will not show the findings this user waved away — which is why
 * 使い方 says so plainly and 「すべて戻す」 is one button.
 *
 * A finding's identity has to survive a re-check after an edit, so the key is
 * built from what the finding *is* (rule, paragraph, matched text) rather than
 * where it sits: applying a fix elsewhere in the paragraph shifts every offset
 * after it. The trade-off is that two identical matches in one paragraph share a
 * key and are ignored together — and that inserting or deleting whole paragraphs
 * renumbers the ones below, so a stored ignore stops matching and its finding
 * comes back. Coming back is the safe direction to fail in, and re-ignoring is
 * one click; silently hiding a finding the user never dismissed would not be.
 */
import type { Category, Finding, Severity } from "../core/types.ts";
import { CATEGORIES } from "../core/types.ts";

export function ignoreKey(finding: Finding): string {
  return `${finding.ruleId}${finding.paragraphIndex}${finding.matched}`;
}

export class IgnoreList {
  /** key → the finding as it looked when it was ignored, for the list display. */
  private readonly items = new Map<string, Finding>();

  /**
   * Called after every change the user makes, so the pane can write the list
   * back to the document. Restoring from the document does *not* fire it: that
   * would save what was just read, on every open, for no reason.
   */
  private readonly onChange: () => void;

  // 引数プロパティ（constructor(private readonly …)）にはしない。node --test は
  // 型を剥がすだけで変換はしないので、走らせた瞬間に構文エラーになる。
  constructor(onChange: () => void = () => undefined) {
    this.onChange = onChange;
  }

  add(finding: Finding): void {
    this.items.set(ignoreKey(finding), finding);
    this.onChange();
  }

  /** 「まとめて無視」 — one change, so the document is written once, not once per finding. */
  addAll(findings: readonly Finding[]): void {
    for (const finding of findings) this.items.set(ignoreKey(finding), finding);
    this.onChange();
  }

  remove(key: string): void {
    this.items.delete(key);
    this.onChange();
  }

  has(finding: Finding): boolean {
    return this.items.has(ignoreKey(finding));
  }

  clear(): void {
    this.items.clear();
    this.onChange();
  }

  /** Replaces the whole list with what was stored in the document. */
  restore(findings: readonly Finding[]): void {
    this.items.clear();
    for (const finding of findings) this.items.set(ignoreKey(finding), finding);
  }

  get size(): number {
    return this.items.size;
  }

  /** Ignored findings in document order, each with the key needed to restore it. */
  entries(): Array<{ key: string; finding: Finding }> {
    return [...this.items.entries()]
      .map(([key, finding]) => ({ key, finding }))
      .sort((a, b) => a.finding.paragraphIndex - b.finding.paragraphIndex || a.finding.start - b.finding.start);
  }

  /** The findings themselves, in document order — what gets stored. */
  findings(): Finding[] {
    return this.entries().map(({ finding }) => finding);
  }

  /** Drops the findings the user has chosen not to see. */
  filter(findings: readonly Finding[]): Finding[] {
    return findings.filter((f) => !this.has(f));
  }
}

// --- 原稿ファイルに残す形 ---------------------------------------------------
//
// What is written is a plain array of findings, and what is read back is
// checked field by field. It has to be: this comes out of a file that anything
// could have touched — an older version of this add-in, a hand edit, a
// conversion through another program — and one malformed entry must not cost
// the user the rest of the list, let alone stop the pane from opening.

/**
 * A cap on how much of this goes into somebody's manuscript.
 *
 * Reached only by ignoring findings in bulk over and over; a normal draft
 * produces tens. It exists so that a runaway list cannot quietly add megabytes
 * to a file the user then mails to somebody.
 */
export const MAX_IGNORED = 2000;

const SEVERITIES: readonly Severity[] = ["fix", "confirm", "note"];

/** One stored entry, or null when it is not a finding this version understands. */
function parseFinding(raw: unknown): Finding | null {
  if (raw === null || typeof raw !== "object") return null;
  const source = raw as Record<string, unknown>;
  const text = (value: unknown): string | null => (typeof value === "string" ? value : null);
  const whole = (value: unknown): number | null =>
    typeof value === "number" && Number.isInteger(value) && value >= 0 ? value : null;

  const ruleId = text(source.ruleId);
  const matched = text(source.matched);
  const message = text(source.message);
  const paragraphIndex = whole(source.paragraphIndex);
  const start = whole(source.start);
  const end = whole(source.end);
  if (ruleId === null || matched === null || message === null) return null;
  if (paragraphIndex === null || start === null || end === null) return null;

  const category = text(source.category);
  const severity = text(source.severity);
  if (category === null || !(category in CATEGORIES)) return null;
  if (severity === null || !(SEVERITIES as readonly string[]).includes(severity)) return null;

  const replacement = text(source.replacement);
  return {
    ruleId,
    category: category as Category,
    severity: severity as Severity,
    paragraphIndex,
    start,
    end,
    matched,
    message,
    ...(replacement === null ? {} : { replacement }),
  };
}

/** Reads whatever was stored, keeping the entries that still make sense. */
export function parseIgnored(raw: unknown): Finding[] {
  if (!Array.isArray(raw)) return [];
  const findings: Finding[] = [];
  for (const entry of raw) {
    const finding = parseFinding(entry);
    if (finding !== null) findings.push(finding);
    if (findings.length >= MAX_IGNORED) break;
  }
  return findings;
}
